"use client";

import { createContext, useContext, useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";
import { User, Session } from "@supabase/supabase-js";
import { useRouter, usePathname } from "next/navigation";

interface AuthContextType {
    user: User | null;
    session: Session | null;
    loading: boolean;
    signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
    user: null,
    session: null,
    loading: true,
    signOut: async () => { },
});

export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
    const [user, setUser] = useState<User | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [loading, setLoading] = useState(true);
    const router = useRouter();
    const _pathname = usePathname();

    useEffect(() => {
        // Get initial session
        supabase.auth.getSession().then(({ data: { session } }: { data: { session: Session | null } }) => {
            setSession(session);
            setUser(session?.user ?? null);
            setLoading(false);
        });

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event: any, session: Session | null) => {
            setSession(session);
            setUser(session?.user ?? null);
            setLoading(false);
        });

        return () => {
            subscription.unsubscribe();
        };
    }, []);

    const signOut = async () => {
        await supabase.auth.signOut();
        router.push("/");
    };

    return (
        <AuthContext.Provider value={{ user, session, loading, signOut }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => useContext(AuthContext);

"use client";

import { useState, useEffect, useRef } from "react";

const W = 480, H = 280;
const PAD = { top: 28, right: 24, bottom: 44, left: 54 };
const pW = W - PAD.left - PAD.right, pH = H - PAD.top - PAD.bottom;
const X_MIN = -4, X_MAX = 4, Y_MIN = -1.5, Y_MAX = 1.5;

function toX(x: number) { return PAD.left + ((x - X_MIN) / (X_MAX - X_MIN)) * pW; }
function toY(y: number) { return PAD.top + pH - ((y - Y_MIN) / (Y_MAX - Y_MIN)) * pH; }

interface ActivationFunction {
    key: string;
    label: string;
    color: string;
    fn: (x: number) => number;
    deriv: (x: number) => number;
    desc: string;
}

const FUNS: ActivationFunction[] = [
    { key: "relu", label: "ReLU", color: "#60a5fa", fn: x => Math.max(0, x), deriv: x => (x > 0 ? 1 : 0), desc: "max(0,x) ΓÇö sparsity, fast, but dying neurons" },
    { key: "sigmoid", label: "Sigmoid", color: "#f472b8", fn: x => 1 / (1 + Math.exp(-x)), deriv: x => { const s = 1 / (1 + Math.exp(-x)); return s * (1 - s); }, desc: "1/(1+eΓü╗╦ú) ΓÇö outputs probability, saturates at extremes" },
    { key: "tanh", label: "Tanh", color: "#fbbf24", fn: x => Math.tanh(x), deriv: x => 1 - Math.tanh(x) ** 2, desc: "tanh(x) ΓÇö zero-centred, stronger gradients" },
    { key: "leaky", label: "Leaky ReLU", color: "#34d399", fn: x => (x > 0 ? x : 0.1 * x), deriv: x => (x > 0 ? 1 : 0.1), desc: "max(0.1x,x) ΓÇö prevents dying neurons" },
    { key: "gelu", label: "GELU", color: "#a78bfa", fn: x => 0.5 * x * (1 + Math.tanh(Math.sqrt(2 / Math.PI) * (x + 0.044715 * x ** 3))), deriv: x => { const c = Math.sqrt(2 / Math.PI); const t = Math.tanh(c * (x + 0.044715 * x ** 3)); return 0.5 * (1 + t) + 0.5 * x * (1 - t ** 2) * c * (1 + 3 * 0.044715 * x ** 2); }, desc: "Smooth ReLU ΓÇö used in Transformers (GPT/BERT)." },
];

const THEME = { bg: "#08090d", surface: "#0d0e18", border: "#1a1b2c", text: "#e2e8f0", dim: "#374151", grid: "#111827" };

export default function ActivationFunctionPrimitive() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [active, setActive] = useState(new Set(["relu", "sigmoid", "tanh"]));
    const [showDeriv, setShowDeriv] = useState(false);
    const [queryX, setQueryX] = useState(1.5);

    const toggle = (key: string) => setActive(prev => {
        const n = new Set(prev);
        if (n.has(key)) n.delete(key);
        else n.add(key);
        return n;
    });

    useEffect(() => { draw(); }, [active, showDeriv, queryX]);

    function draw() {
        const canvas = canvasRef.current; if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        ctx.clearRect(0, 0, W, H); ctx.fillStyle = THEME.surface; ctx.fillRect(0, 0, W, H);

        // Grid
        ctx.strokeStyle = THEME.grid; ctx.lineWidth = 1;
        [-1, 0, 1].forEach(v => {
            const y = toY(v);
            ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + pW, y); ctx.stroke();
            ctx.fillStyle = THEME.dim; ctx.font = "9px monospace"; ctx.textAlign = "right";
            ctx.fillText(v.toString(), PAD.left - 4, y + 4);
        });
        [-4, -2, 0, 2, 4].forEach(v => {
            const x = toX(v);
            ctx.beginPath(); ctx.moveTo(x, PAD.top); ctx.lineTo(x, PAD.top + pH); ctx.stroke();
            ctx.fillStyle = THEME.dim; ctx.font = "9px monospace"; ctx.textAlign = "center";
            ctx.fillText(v.toString(), x, PAD.top + pH + 14);
        });

        // Zero axes
        ctx.beginPath(); ctx.moveTo(toX(0), PAD.top); ctx.lineTo(toX(0), PAD.top + pH);
        ctx.strokeStyle = "#ffffff22"; ctx.lineWidth = 1; ctx.stroke();
        ctx.beginPath(); ctx.moveTo(PAD.left, toY(0)); ctx.lineTo(PAD.left + pW, toY(0));
        ctx.stroke();

        // Draw each function
        FUNS.filter(f => active.has(f.key)).forEach(f => {
            // Main function
            ctx.beginPath();
            let started = false;
            for (let i = 0; i <= 200; i++) {
                const x = X_MIN + (i / 200) * (X_MAX - X_MIN);
                const y = f.fn(x);
                const cx = toX(x), cy = toY(y);
                if (cy < PAD.top - 5 || cy > PAD.top + pH + 5) { started = false; continue; }
                if (!started) { ctx.moveTo(cx, cy); started = true; } else ctx.lineTo(cx, cy);
            }
            ctx.strokeStyle = f.color; ctx.lineWidth = 2.5;
            ctx.shadowColor = f.color; ctx.shadowBlur = 6; ctx.stroke(); ctx.shadowBlur = 0;

            // Derivative (dashed)
            if (showDeriv) {
                ctx.beginPath(); started = false;
                for (let i = 0; i <= 200; i++) {
                    const x = X_MIN + (i / 200) * (X_MAX - X_MIN);
                    const y = f.deriv(x);
                    const cx = toX(x), cy = toY(y);
                    if (cy < PAD.top - 5 || cy > PAD.top + pH + 5) { started = false; continue; }
                    if (!started) { ctx.moveTo(cx, cy); started = true; } else ctx.lineTo(cx, cy);
                }
                ctx.strokeStyle = f.color + "88"; ctx.lineWidth = 1.2; ctx.setLineDash([4, 3]); ctx.stroke(); ctx.setLineDash([]);
            }
        });

        // Query line
        const qx = toX(queryX);
        ctx.beginPath(); ctx.moveTo(qx, PAD.top); ctx.lineTo(qx, PAD.top + pH);
        ctx.strokeStyle = "#fbbf2444"; ctx.lineWidth = 1; ctx.setLineDash([3, 2]); ctx.stroke(); ctx.setLineDash([]);
        ctx.fillStyle = "#fbbf24"; ctx.font = "bold 9px monospace"; ctx.textAlign = "center";
        ctx.fillText(`x=${queryX.toFixed(1)}`, qx, PAD.top + 8);

        // Query dots
        FUNS.filter(f => active.has(f.key)).forEach(f => {
            const y = f.fn(queryX);
            if (y < Y_MIN || y > Y_MAX) return;
            const cy = toY(y);
            ctx.beginPath(); ctx.arc(qx, cy, 5, 0, Math.PI * 2);
            ctx.fillStyle = f.color; ctx.shadowColor = f.color; ctx.shadowBlur = 10; ctx.fill(); ctx.shadowBlur = 0;
        });

        // Axes
        ctx.strokeStyle = "#252535"; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(PAD.left, PAD.top); ctx.lineTo(PAD.left, PAD.top + pH);
        ctx.lineTo(PAD.left + pW, PAD.top + pH); ctx.stroke();
        ctx.fillStyle = THEME.dim; ctx.font = "10px monospace"; ctx.textAlign = "center";
        ctx.fillText("x \u2192", PAD.left + pW / 2, H - 6);
        ctx.save(); ctx.translate(13, PAD.top + pH / 2); ctx.rotate(-Math.PI / 2);
        ctx.fillText("f(x)", 0, 0); ctx.restore();
    }

    return (
        <div style={{ fontFamily: "'SF Mono','Fira Code',monospace", background: THEME.bg, padding: "24px 20px", color: THEME.text, borderRadius: "8px", border: `1px solid ${THEME.border}`, maxWidth: 800, margin: "0 auto" }}>
            <div style={{ textAlign: "center", marginBottom: "16px" }}>
                <div style={{ fontSize: "10px", letterSpacing: "4px", color: THEME.dim, marginBottom: "6px" }}>SUBJECT VI ┬╖ DEEP LEARNING ┬╖ ┬º71</div>
                <h1 style={{ fontSize: "24px", fontWeight: 700, margin: "0 0 4px" }}>Activation Functions</h1>
                <p style={{ fontSize: "12px", color: THEME.dim, margin: 0, fontStyle: "italic" }}>
                    "Without activations, deep networks collapse to a single linear layer. Non-linearity is what gives depth meaning."
                </p>
            </div>

            <div style={{ display: "flex", gap: "6px", marginBottom: "10px", flexWrap: "wrap", justifyContent: "center" }}>
                {FUNS.map(f => (
                    <button key={f.key} onClick={() => toggle(f.key)}
                        style={{ padding: "5px 12px", border: `2px solid ${active.has(f.key) ? f.color : THEME.border}`, borderRadius: "4px", background: active.has(f.key) ? f.color + "22" : "transparent", color: active.has(f.key) ? f.color : THEME.dim, fontSize: "11px", fontFamily: "inherit", cursor: "pointer", fontWeight: active.has(f.key) ? 700 : 400, transition: "all 0.2s" }}>
                        {f.label}
                    </button>
                ))}
                <button onClick={() => setShowDeriv(s => !s)}
                    style={{ padding: "5px 12px", border: `2px solid ${showDeriv ? "#ffffff55" : THEME.border}`, borderRadius: "4px", background: showDeriv ? "#ffffff11" : "transparent", color: showDeriv ? "#fff" : THEME.dim, fontSize: "11px", fontFamily: "inherit", cursor: "pointer" }}>
                    {showDeriv ? "Hide f'(x)" : "Show f'(x)"}
                </button>
            </div>

            <div style={{ border: `1px solid ${THEME.border}`, borderRadius: "8px", overflow: "hidden", marginBottom: "10px", background: THEME.surface }}>
                <canvas ref={canvasRef} width={W} height={H} style={{ display: "block", margin: "0 auto" }} />
            </div>

            <div style={{ width: "100%", maxWidth: 440, margin: "0 auto 14px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "11px", color: THEME.dim, marginBottom: "4px" }}>
                    <span>Query x</span><span style={{ color: "#fbbf24" }}>{queryX.toFixed(2)}</span>
                </div>
                <input type="range" min={X_MIN} max={X_MAX} step={0.05} value={queryX}
                    onChange={e => setQueryX(+e.target.value)}
                    style={{ width: "100%", accentColor: "#fbbf24", cursor: "pointer" }} />
            </div>

            {/* Value table */}
            <div style={{ background: THEME.surface, border: `1px solid ${THEME.border}`, borderRadius: "8px", overflow: "hidden", maxWidth: 480, width: "100%", margin: "0 auto 14px" }}>
                <div style={{ display: "grid", gridTemplateColumns: `repeat(${showDeriv ? 4 : 3}, 1fr)`, background: THEME.border }}>
                    {["Function", "f(x)", "Range", showDeriv ? "f'(x)" : null].filter(Boolean).map(h => (
                        <div key={h!} style={{ padding: "6px 10px", fontSize: "9px", color: THEME.dim, letterSpacing: "1px", textAlign: "center" }}>{h}</div>
                    ))}
                </div>
                {FUNS.filter(f => active.has(f.key)).map(f => {
                    const y = f.fn(queryX), dy = f.deriv(queryX);
                    return (
                        <div key={f.key} style={{ display: "grid", gridTemplateColumns: `repeat(${showDeriv ? 4 : 3}, 1fr)`, borderTop: `1px solid ${THEME.border}` }}>
                            <div style={{ padding: "7px 10px", fontSize: "10px", color: f.color, fontWeight: 700 }}>{f.label}</div>
                            <div style={{ padding: "7px 10px", fontSize: "11px", color: f.color, textAlign: "center", fontWeight: 700 }}>{y.toFixed(4)}</div>
                            <div style={{ padding: "7px 10px", fontSize: "9px", color: THEME.dim, textAlign: "center" }}>{f.key === "relu" ? "[0,\u221E)" : f.key === "sigmoid" ? "(0,1)" : f.key === "tanh" ? "(-1,1)" : "(-\u221E,\u221E)"}</div>
                            {showDeriv && <div style={{ padding: "7px 10px", fontSize: "11px", color: f.color + "aa", textAlign: "center" }}>{dy.toFixed(4)}</div>}
                        </div>
                    );
                })}
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px", maxWidth: 480, width: "100%", margin: "0 auto" }}>
                {[
                    { label: "Vanishing gradient", color: "#f87171", desc: "Sigmoid/Tanh saturate \u2192 tiny gradients \u2192 no learning" },
                    { label: "Dying ReLU", color: "#fbbf24", desc: "ReLU outputs 0 for x<0 \u2192 some neurons never activate" },
                    { label: "Zero-centred", color: "#34d399", desc: "Tanh is zero-centred \u2192 faster convergence than sigmoid" },
                    { label: "Modern default", color: "#a78bfa", desc: "GELU used in Transformers; ReLU still dominates CNNs" },
                ].map(({ label, color, desc }) => (
                    <div key={label} style={{ border: `1px solid ${color}33`, borderRadius: "6px", padding: "8px 10px", background: color + "08" }}>
                        <div style={{ fontSize: "10px", color, fontWeight: 700, marginBottom: "3px" }}>{label}</div>
                        <div style={{ fontSize: "9px", color: THEME.dim, lineHeight: 1.6 }}>{desc}</div>
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef } from "react";

const THEME = {
    bg: "#07080c", surface: "#0c0d16", border: "#181826",
    text: "#e2e8f0", dim: "#4a5568",
    q: "#f472b8", k: "#60a5fa", v: "#34d399", attn: "#fbbf24",
};

const SENTENCE = ["The", "cat", "sat", "on", "the", "mat"];
const N = SENTENCE.length;

function softmax(arr: number[]) {
    const max = Math.max(...arr);
    const exps = arr.map(x => Math.exp(x - max));
    const sum = exps.reduce((s, e) => s + e, 0);
    return exps.map(e => e / sum);
}

// Simulate Q\u22C5K^T attention scores
const RAW_SCORES = [
    [3.2, 0.8, 0.4, 0.2, 2.8, 0.5],  // "The" attends mostly to "the"
    [0.6, 3.5, 2.1, 0.3, 0.4, 1.8],  // "cat" attends to "cat","sat","mat"
    [0.4, 2.3, 3.8, 0.8, 0.3, 1.4],  // "sat" attends to "sat","cat"
    [0.2, 0.3, 0.7, 3.1, 0.2, 0.9],  // "on" attends to "on"
    [2.9, 0.5, 0.3, 0.2, 3.3, 0.4],  // "the" attends to "the","The"
    [0.5, 1.9, 1.6, 0.8, 0.4, 3.6],  // "mat" attends to "mat","cat","sat"
];

const ATTN = RAW_SCORES.map(row => softmax(row));

export default function AttentionPrimitive() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [queryWord, setQueryWord] = useState(1); // "cat"
    const [dim, setDim] = useState(64);

    const attnRow = ATTN[queryWord];

    useEffect(() => { draw(); }, [queryWord, dim]);

    function draw() {
        const canvas = canvasRef.current; if (!canvas) return;
        const CW = canvas.width, CH = canvas.height;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = THEME.surface; ctx.fillRect(0, 0, CW, CH);

        const CELL = Math.floor(Math.min(CW, CH - 30) / (N + 1.5));
        const OFFSET = 64;

        // Draw full attention matrix
        ATTN.forEach((row, qi) => {
            row.forEach((score, ki) => {
                const isQueryRow = qi === queryWord;
                const x = OFFSET + ki * CELL, y = 30 + qi * CELL;
                const intensity = score;
                ctx.fillStyle = `rgba(251,191,36,${isQueryRow ? intensity : intensity * 0.3})`;
                ctx.fillRect(x, y, CELL - 2, CELL - 2);
                ctx.strokeStyle = isQueryRow ? THEME.attn + "88" : "#ffffff08";
                ctx.lineWidth = isQueryRow ? 1.5 : 0.5; ctx.strokeRect(x, y, CELL - 2, CELL - 2);
                // Score text
                if (CELL > 28) {
                    ctx.fillStyle = isQueryRow ? "#000" : "#ffffff44";
                    ctx.font = `${isQueryRow ? "bold " : ""}${CELL > 36 ? 9 : 8}px monospace`;
                    ctx.textAlign = "center"; ctx.textBaseline = "middle";
                    ctx.fillText(score.toFixed(2), x + CELL / 2, y + CELL / 2);
                    ctx.textBaseline = "alphabetic";
                }
            });
        });

        // Row/col labels
        ctx.font = "10px 'SF Mono',monospace"; ctx.textAlign = "right";
        SENTENCE.forEach((w, i) => {
            const isQ = i === queryWord;
            ctx.fillStyle = isQ ? THEME.q : THEME.dim;
            ctx.fillText(w, OFFSET - 6, 30 + i * CELL + CELL / 2 + 4);
        });
        ctx.textAlign = "center";
        SENTENCE.forEach((w, i) => {
            ctx.fillStyle = THEME.k;
            ctx.fillText(w, OFFSET + i * CELL + CELL / 2, 24);
        });

        // Query indicator
        ctx.fillStyle = THEME.q + "22";
        ctx.fillRect(2, 30 + queryWord * CELL, OFFSET - 4, CELL - 2);
        ctx.fillStyle = THEME.q; ctx.font = "bold 8px monospace"; ctx.textAlign = "center";
        ctx.fillText("Q\u2192", OFFSET / 2, 30 + queryWord * CELL + CELL / 2 + 3);

        // Axis labels
        ctx.fillStyle = THEME.dim; ctx.font = "9px monospace"; ctx.textAlign = "center";
        ctx.fillText("Keys (K) \u2014 attended TO", OFFSET + N * CELL / 2, CH - 6);
        ctx.save(); ctx.translate(13, 30 + N * CELL / 2); ctx.rotate(-Math.PI / 2);
        ctx.fillText("Queries (Q) \u2014 attending FROM", 0, 0); ctx.restore();
    }

    return (
        <div style={{ fontFamily: "'SF Mono','Fira Code',monospace", background: THEME.bg, padding: "24px 20px", color: THEME.text, borderRadius: "8px", border: `1px solid ${THEME.border}`, maxWidth: 900, margin: "0 auto" }}>
            <div style={{ textAlign: "center", marginBottom: "16px" }}>
                <div style={{ fontSize: "10px", letterSpacing: "4px", color: THEME.dim, marginBottom: "6px" }}>SUBJECT VI ┬╖ DEEP LEARNING ┬╖ ┬º75</div>
                <h1 style={{ fontSize: "24px", fontWeight: 700, margin: "0 0 4px" }}>Attention Mechanism</h1>
                <p style={{ fontSize: "12px", color: THEME.dim, margin: 0, fontStyle: "italic" }}>
                    "Attention lets every word ask: which other words should I pay attention to right now?"
                </p>
            </div>

            <div style={{ display: "flex", gap: "24px", flexWrap: "wrap", justifyContent: "center", alignItems: "flex-start", width: "100%" }}>

                {/* Attention heatmap */}
                <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
                    <div style={{ fontSize: "10px", color: THEME.dim, letterSpacing: "2px", textAlign: "center" }}>ATTENTION MATRIX softmax(QK^T / \u221Ad)</div>
                    <div style={{ border: `1px solid ${THEME.border}`, borderRadius: "8px", overflow: "hidden", background: THEME.surface }}>
                        <canvas ref={canvasRef} width={420} height={280} style={{ display: "block" }} />
                    </div>
                    <div style={{ display: "flex", gap: "12px", justifyContent: "center", fontSize: "10px" }}>
                        {[{ color: THEME.q, label: "Query row" }, { color: THEME.k, label: "Key col" }, { color: THEME.attn, label: "Attention score" }].map(({ color, label }) => (
                            <div key={label} style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                                <div style={{ width: 10, height: 10, borderRadius: "2px", background: color }} />
                                <span style={{ color: THEME.dim }}>{label}</span>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Right panel */}
                <div style={{ flex: "1 1 280px", display: "flex", flexDirection: "column", gap: "12px" }}>

                    {/* Query selector */}
                    <div style={{ background: THEME.surface, border: `1px solid ${THEME.border}`, borderRadius: "8px", padding: "12px 14px" }}>
                        <div style={{ fontSize: "10px", color: THEME.dim, letterSpacing: "2px", marginBottom: "8px" }}>QUERY WORD</div>
                        <div style={{ display: "flex", gap: "5px", flexWrap: "wrap" }}>
                            {SENTENCE.map((w, i) => (
                                <button key={i} onClick={() => setQueryWord(i)}
                                    style={{ padding: "4px 10px", border: `1.5px solid ${queryWord === i ? THEME.q : THEME.border}`, borderRadius: "4px", background: queryWord === i ? THEME.q + "22" : "transparent", color: queryWord === i ? THEME.q : THEME.dim, fontSize: "11px", fontFamily: "inherit", cursor: "pointer" }}>
                                    {w}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Attention weights for selected query */}
                    <div style={{ background: THEME.surface, border: `1px solid ${THEME.q}44`, borderRadius: "8px", padding: "12px 14px" }}>
                        <div style={{ fontSize: "10px", color: THEME.q, letterSpacing: "2px", marginBottom: "10px" }}>
                            "{SENTENCE[queryWord]}" ATTENDS TO\u2026
                        </div>
                        {SENTENCE.map((word, ki) => {
                            const score = attnRow[ki];
                            return (
                                <div key={ki} style={{ marginBottom: "7px" }}>
                                    <div style={{ display: "flex", justifyContent: "space-between", fontSize: "11px", marginBottom: "3px" }}>
                                        <span style={{ color: ki === queryWord ? THEME.attn : THEME.text }}>{word}</span>
                                        <span style={{ color: THEME.attn, fontWeight: 700 }}>{(score * 100).toFixed(1)}%</span>
                                    </div>
                                    <div style={{ height: 8, background: "#1e1e35", borderRadius: "4px", overflow: "hidden" }}>
                                        <div style={{ height: "100%", width: `${score * 100}%`, background: `linear-gradient(90deg,${THEME.attn}88,${THEME.attn})`, borderRadius: "4px", transition: "width 0.4s" }} />
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {/* Formula */}
                    <div style={{ background: THEME.surface, border: `1px solid ${THEME.border}`, borderRadius: "8px", padding: "12px 14px" }}>
                        <div style={{ fontSize: "10px", color: THEME.dim, letterSpacing: "2px", marginBottom: "8px" }}>FORMULA</div>
                        <div style={{ fontSize: "11px", fontFamily: "monospace", lineHeight: 2.2 }}>
                            <div><span style={{ color: THEME.q }}>Q</span> = W_Q \u22C5 x <span style={{ color: THEME.dim }}>(what I want)</span></div>
                            <div><span style={{ color: THEME.k }}>K</span> = W_K \u22C5 x <span style={{ color: THEME.dim }}>(what I have)</span></div>
                            <div><span style={{ color: THEME.v }}>V</span> = W_V \u22C5 x <span style={{ color: THEME.dim }}>(what I give)</span></div>
                            <div style={{ marginTop: 6, color: "#fff" }}>
                                Attn = softmax(QKß╡Ç / \u221Ad) \u22C5 V
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* ΓêÜd slider */}
            <div style={{ width: "100%", maxWidth: 1000, margin: "20px auto 0" }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "11px", color: THEME.dim, marginBottom: "4px" }}>
                    <span>Dimension d (scaling factor)</span>
                    <span style={{ color: THEME.attn }}>\u221Ad = {Math.sqrt(dim).toFixed(1)}</span>
                </div>
                <input type="range" min={4} max={256} step={4} value={dim}
                    onChange={e => setDim(+e.target.value)}
                    style={{ width: "100%", accentColor: THEME.attn, cursor: "pointer" }} />
                <div style={{ fontSize: "9px", color: THEME.dim, marginTop: "3px" }}>Larger d \u2192 softer attention (prevents gradient vanishing/explosion)</div>
            </div>

            <div style={{ marginTop: "14px", padding: "10px 18px", borderLeft: `3px solid ${THEME.attn}`, background: THEME.attn + "0f", maxWidth: 800, margin: "14px auto 0", fontSize: "11px", color: THEME.dim, lineHeight: 1.8, borderRadius: "0 4px 4px 0" }}>
                <span style={{ color: THEME.attn }}>// INSIGHT:</span> Each row of the attention matrix is a probability distribution. "cat" attends to "sat" and "mat" \u2014 semantically related tokens over which information is pooled.
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { motion } from "framer-motion";

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const W = 600, H = 180;
const X_PAD = 60;
const X_MIN = 0, X_MAX = 100;
const FIXED_POINTS = [18, 22, 25, 27, 30, 31, 33, 35, 38, 40, 42, 45, 47, 50];

// ΓöÇΓöÇΓöÇ Math Utils ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function toCanvas(v: number) { return X_PAD + ((v - X_MIN) / (X_MAX - X_MIN)) * (W - 2 * X_PAD); }
function fromCanvas(cx: number) { return X_MIN + ((cx - X_PAD) / (W - 2 * X_PAD)) * (X_MAX - X_MIN); }
function clamp(v: number, lo: number, hi: number) { return Math.max(lo, Math.min(hi, v)); }

function computeStats(pts: number[]) {
    const sorted = [...pts].sort((a, b) => a - b);
    const mean = pts.reduce((a, b) => a + b, 0) / pts.length;
    const mid = Math.floor(sorted.length / 2);
    const median = sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid];

    // Mode: most frequent (binned for visual stability)
    const bins: Record<number, number> = {};
    pts.forEach(v => { const b = Math.round(v / 5) * 5; bins[b] = (bins[b] || 0) + 1; });
    const sortedBins = Object.entries(bins).sort((a, b) => b[1] - a[1]);
    const modeVal = sortedBins.length > 0 ? +sortedBins[0][0] : mean;

    return { mean, median, mode: modeVal };
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function CentralTendencyPrimitive() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [outlier, setOutlier] = useState(55);
    const [dragging, setDragging] = useState(false);

    const allPoints = useMemo(() => [...FIXED_POINTS, outlier], [outlier]);
    const stats = useMemo(() => computeStats(allPoints), [allPoints]);

    const [reducedMotion, setReducedMotion] = useState(() => {
        if (typeof window === "undefined") return false;
        return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    });

    useEffect(() => {
        const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
        const handler = (e: MediaQueryListEvent) => setReducedMotion(e.matches);
        mediaQuery.addEventListener("change", handler);
        return () => mediaQuery.removeEventListener("change", handler);
    }, []);

    const render = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        const Y_MID = H / 2;
        ctx.clearRect(0, 0, W, H);

        // Grid System (Subtle Background)
        ctx.strokeStyle = "rgba(255, 255, 255, 0.03)";
        ctx.lineWidth = 1;
        [20, 40, 60, 80].forEach(v => {
            const cx = toCanvas(v);
            ctx.beginPath(); ctx.moveTo(cx, 0); ctx.lineTo(cx, H); ctx.stroke();
        });

        // Main Axis
        ctx.strokeStyle = "rgba(255, 255, 255, 0.1)";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(X_PAD, Y_MID + 35);
        ctx.lineTo(W - X_PAD, Y_MID + 35);
        ctx.stroke();

        // Ticks & Labels
        ctx.fillStyle = "rgba(255, 255, 255, 0.3)";
        ctx.font = "10px var(--font-jetbrains)";
        ctx.textAlign = "center";
        [0, 20, 40, 60, 80, 100].forEach(v => {
            const cx = toCanvas(v);
            ctx.beginPath();
            ctx.moveTo(cx, Y_MID + 35);
            ctx.lineTo(cx, Y_MID + 42);
            ctx.stroke();
            ctx.fillText(v.toString(), cx, Y_MID + 55);
        });

        // Fixed Density Points
        FIXED_POINTS.forEach(v => {
            const cx = toCanvas(v);
            ctx.beginPath();
            ctx.arc(cx, Y_MID, 4, 0, Math.PI * 2);
            ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
            ctx.fill();
        });

        // Draggable Outlier
        const ocx = toCanvas(outlier);
        ctx.save();
        ctx.shadowBlur = 15;
        ctx.shadowColor = "hsl(var(--accent))";
        ctx.beginPath();
        ctx.arc(ocx, Y_MID, 8, 0, Math.PI * 2);
        ctx.fillStyle = "hsl(var(--accent))";
        ctx.fill();
        ctx.restore();

        // Outlier Label
        ctx.fillStyle = "black";
        ctx.font = "bold 9px var(--font-jetbrains)";
        ctx.fillText("X", ocx, Y_MID + 3.5);

        // Indicators Data
        const indicators = [
            { val: stats.mean, color: "hsl(var(--primary))", label: "Mean", yOff: -55 },
            { val: stats.median, color: "hsl(var(--secondary))", label: "Median", yOff: -38 },
            { val: stats.mode, color: "#10b981", label: "Mode", yOff: -21 },
        ];

        indicators.forEach(({ val, color, label, yOff }) => {
            const cx = toCanvas(val);

            // Vertical dashed line
            ctx.beginPath();
            ctx.setLineDash([4, 4]);
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.moveTo(cx, Y_MID - 20);
            ctx.lineTo(cx, Y_MID + 35);
            ctx.stroke();
            ctx.setLineDash([]);

            // Triangle Pointer
            ctx.beginPath();
            ctx.moveTo(cx - 5, Y_MID - 20);
            ctx.lineTo(cx + 5, Y_MID - 20);
            ctx.lineTo(cx, Y_MID - 12);
            ctx.fillStyle = color;
            ctx.fill();

            // Text Label
            ctx.font = "bold 10px var(--font-jetbrains)";
            ctx.fillStyle = color;
            ctx.textAlign = "center";
            ctx.fillText(`${label}: ${val.toFixed(1)}`, cx, Y_MID + yOff);
        });

    }, [outlier, stats]);

    useEffect(() => { render(); }, [render]);

    const handlePointerMove = useCallback((e: React.PointerEvent) => {
        if (!dragging || !canvasRef.current) return;
        const rect = canvasRef.current.getBoundingClientRect();
        const cx = e.clientX - rect.left;
        const scaleX = W / rect.width;
        setOutlier(clamp(Math.round(fromCanvas(cx * scaleX)), 0, 100));
    }, [dragging]);

    const divergence = stats.mean - stats.median;
    const isSkewed = Math.abs(divergence) > 5;

    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="space-y-1">
                    <h3 className="text-sm font-bold text-muted uppercase tracking-wider flex items-center gap-2">
                        <span className="material-symbols-outlined text-base">balance</span>
                        Balance & Typicality
                    </h3>
                    <p className="text-xs text-muted/60 lowercase italic">Outlier sensitivity visualization</p>
                </div>
                <div className={`px-3 py-1.5 rounded-full border text-[10px] font-bold tracking-widest uppercase transition-all ${isSkewed ? 'bg-amber-500/10 border-amber-500/50 text-amber-500' : 'bg-emerald-500/10 border-emerald-500/50 text-emerald-500'
                    }`}>
                    {isSkewed ? 'Skew detected' : 'Near Symmetric'}
                </div>
            </div>

            <div
                className={`relative rounded bg-slate-950/40 border border-border/50 overflow-hidden shadow-2xl transition-all cursor-${dragging ? 'grabbing' : 'grab'}`}
                onPointerDown={(e) => {
                    const rect = canvasRef.current?.getBoundingClientRect();
                    if (!rect) return;
                    const cx = (e.clientX - rect.left) * (W / rect.width);
                    const ocx = toCanvas(outlier);
                    if (Math.abs(cx - ocx) < 25) {
                        setDragging(true);
                        (e.target as HTMLElement).setPointerCapture(e.pointerId);
                    }
                }}
                onPointerMove={handlePointerMove}
                onPointerUp={(e) => {
                    setDragging(false);
                    (e.target as HTMLElement).releasePointerCapture(e.pointerId);
                }}
            >
                <canvas ref={canvasRef} width={W} height={H} className="w-full h-auto block touch-none" />

                {/* Interaction hint */}
                <div className="absolute top-3 right-3 flex items-center gap-2 px-2 py-1 bg-black/40 rounded border border-white/5 pointer-events-none">
                    <span className="material-symbols-outlined text-[12px] text-accent animate-pulse">drag_pan</span>
                    <span className="text-[9px] font-bold text-muted/50 uppercase">Drag Outlier</span>
                </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                {[
                    { label: "Mean", val: stats.mean, color: "text-primary", bg: "bg-primary/5", border: "border-primary/20", icon: "average", desc: "Outlier magnet" },
                    { label: "Median", val: stats.median, color: "text-secondary", bg: "bg-secondary/5", border: "border-secondary/20", icon: "view_day", desc: "Positional pivot" },
                    { label: "Mode", val: stats.mode, color: "text-emerald-500", bg: "bg-emerald-500/5", border: "border-emerald-500/20", icon: "category", desc: "Density peak" },
                ].map((item) => (
                    <div key={item.label} className={`p-4 rounded-lg border ${item.bg} ${item.border} space-y-1 transition-all`}>
                        <div className="flex items-center justify-between">
                            <span className={`text-[10px] font-bold uppercase tracking-wider ${item.color}`}>{item.label}</span>
                            <span className={`material-symbols-outlined text-sm ${item.color}`}>{item.icon}</span>
                        </div>
                        <div className="text-2xl font-bold font-mono tracking-tighter tabular-nums text-foreground">
                            {item.val.toFixed(1)}
                        </div>
                        <p className="text-[10px] text-muted/50 italic leading-none">{item.desc}</p>
                    </div>
                ))}
            </div>

            <div className={`p-4 rounded-lg border flex gap-3 transition-colors ${isSkewed ? 'bg-primary/5 border-primary/10' : 'bg-surface border-border/30'
                }`}>
                <span className={`material-symbols-outlined ${isSkewed ? 'text-primary' : 'text-muted'}`}>
                    {isSkewed ? 'trending_up' : 'info'}
                </span>
                <div className="space-y-1">
                    <p className="text-xs text-muted leading-relaxed">
                        <span className="text-foreground font-bold uppercase tracking-tighter">Observational Gap:</span>
                        The divergence between Mean and Median is <span className="font-mono font-bold text-primary">{Math.abs(divergence).toFixed(2)}</span>.
                        {isSkewed ? (
                            " Notice how the Mean is 'pulled' toward the extreme value, while the Median remains anchored in the data cluster."
                        ) : (
                            " When data is symmetric, the Mean and Median overlap perfectly. This is the ideal 'Normal' balance."
                        )}
                    </p>
                    <div className="h-1 w-full bg-border/20 rounded-full overflow-hidden mt-2">
                        <motion.div
                            animate={{ width: `${Math.min(100, Math.abs(divergence) * 2)}%` }}
                            className={`h-full ${isSkewed ? 'bg-primary shadow-[0_0_8px_rgba(var(--primary-rgb),0.5)]' : 'bg-muted'}`}
                        />
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState/*, useEffect*/ } from "react";
import { Highlight, themes } from "prism-react-renderer";

interface CodeEditorProps {
    code: string;
    language?: string;
    editable?: boolean;
    onCodeChange?: (code: string) => void;
    onRun?: (code: string) => void;
}

interface ExecutionResult {
    output: string;
    error?: string;
    image?: string;
}

export default function CodeEditor({
    code: initialCode,
    language = "python",
    editable = true,
    onCodeChange,
    onRun,
}: CodeEditorProps) {
    const [code, setCode] = useState(initialCode);
    const [isRunning, setIsRunning] = useState(false);
    const [result, setResult] = useState<ExecutionResult | null>(null);
    const [copied, setCopied] = useState(false);

    const handleCodeChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const newCode = e.target.value;
        setCode(newCode);
        onCodeChange?.(newCode);
    };

    const handleRun = async () => {
        setIsRunning(true);
        setResult(null);

        try {
            const response = await fetch("/api/run-code", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ language, code }),
            });

            const data = await response.json();
            setResult({
                output: data.output || "",
                error: data.error || undefined,
                image: data.image || undefined,
            });
            onRun?.(code);
        } catch (error) {
            setResult({
                output: "",
                error: String(error),
            });
        } finally {
            setIsRunning(false);
        }
    };

    const handleCopy = async () => {
        await navigator.clipboard.writeText(code);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    return (
        <div className="rounded-lg border border-border overflow-hidden bg-neutral-950">
            {/* Header */}
            <div className="flex items-center justify-between px-4 py-2 border-b border-border bg-neutral-900">
                <span className="text-sm text-muted font-mono">{language}</span>
                <div className="flex items-center gap-2">
                    <button
                        onClick={handleCopy}
                        className="text-xs text-muted hover:text-foreground transition-colors px-2 py-1 rounded"
                    >
                        {copied ? "Copied!" : "Copy"}
                    </button>
                    <button
                        onClick={handleRun}
                        disabled={isRunning}
                        className="text-xs bg-accent hover:bg-accent/80 text-white px-3 py-1 rounded transition-colors disabled:opacity-50"
                    >
                        {isRunning ? "Running..." : "Run Γû╢"}
                    </button>
                </div>
            </div>

            {/* Code Display/Editor */}
            <div className="relative">
                {editable ? (
                    <div className="relative">
                        {/* Highlighted background */}
                        <Highlight
                            theme={themes.nightOwl}
                            code={code}
                            language={language as "python" | "javascript"}
                        >
                            {({ className, style, tokens, getLineProps, getTokenProps }) => (
                                <pre
                                    className={`${className} p-4 text-sm overflow-x-auto`}
                                    style={{ ...style, margin: 0 }}
                                >
                                    {tokens.map((line, i) => (
                                        <div key={i} {...getLineProps({ line })}>
                                            <span className="text-muted/50 mr-4 select-none w-8 inline-block text-right">
                                                {i + 1}
                                            </span>
                                            {line.map((token, key) => (
                                                <span key={key} {...getTokenProps({ token })} />
                                            ))}
                                        </div>
                                    ))}
                                </pre>
                            )}
                        </Highlight>
                        {/* Editable textarea overlay */}
                        <textarea
                            value={code}
                            onChange={handleCodeChange}
                            className="absolute inset-0 w-full h-full bg-transparent text-transparent caret-white font-mono text-sm p-4 pl-16 resize-none outline-none"
                            spellCheck={false}
                        />
                    </div>
                ) : (
                    <Highlight
                        theme={themes.nightOwl}
                        code={code}
                        language={language as "python" | "javascript"}
                    >
                        {({ className, style, tokens, getLineProps, getTokenProps }) => (
                            <pre
                                className={`${className} p-4 text-sm overflow-x-auto`}
                                style={{ ...style, margin: 0 }}
                            >
                                {tokens.map((line, i) => (
                                    <div key={i} {...getLineProps({ line })}>
                                        <span className="text-muted/50 mr-4 select-none w-8 inline-block text-right">
                                            {i + 1}
                                        </span>
                                        {line.map((token, key) => (
                                            <span key={key} {...getTokenProps({ token })} />
                                        ))}
                                    </div>
                                ))}
                            </pre>
                        )}
                    </Highlight>
                )}
            </div>

            {/* Output */}
            {result && (
                <div className="border-t border-border">
                    <div className="px-4 py-2 bg-neutral-900 text-xs text-muted flex justify-between items-center">
                        <span>Output</span>
                        {result.image && <span className="text-[10px] bg-primary/10 text-primary px-1 rounded">Graph Generated</span>}
                    </div>

                    {/* Console Output */}
                    {(result.output || result.error) && (
                        <pre className={`p-4 text-sm font-mono whitespace-pre-wrap ${result.error ? 'text-red-400' : 'text-green-400'}`}>
                            {result.error || result.output}
                        </pre>
                    )}

                    {/* Image Output */}
                    {result.image && (
                        <div className="p-4 bg-white rounded-b-lg flex justify-center">
                            <img
                                src={`data:image/png;base64,${result.image}`}
                                alt="Generated Plot"
                                className="max-w-full h-auto rounded shadow-sm"
                            />
                        </div>
                    )}

                    {!result.output && !result.error && !result.image && (
                        <div className="p-4 text-sm text-muted font-mono">(No output)</div>
                    )}
                </div>
            )}
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";

// ΓöÇΓöÇΓöÇ Constants & Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const W = 600, H = 360;
const M = { top: 30, right: 30, bottom: 50, left: 60 };
const CW = W - M.left - M.right;
const CH = H - M.top - M.bottom;

type DistType = 'normal' | 'binomial' | 'poisson' | 'uniform';

const COLORS: Record<DistType, string> = {
    normal: "hsl(var(--primary))",
    binomial: "hsl(var(--secondary))",
    poisson: "#10b981", // Emerald
    uniform: "hsl(var(--accent))",
};

// ΓöÇΓöÇΓöÇ Math Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function _factorial(n: number): number {
    if (n <= 1) return 1;
    let res = 1;
    for (let i = 2; i <= n; i++) res *= i;
    return res;
}

function binomCoeff(n: number, k: number): number {
    if (k < 0 || k > n) return 0;
    if (k === 0 || k === n) return 1;
    if (k > n / 2) k = n - k;
    let c = 1;
    for (let i = 0; i < k; i++) c *= (n - i) / (i + 1);
    return c;
}

function normalPDF(x: number, mu: number, sigma: number) {
    return Math.exp(-0.5 * ((x - mu) / sigma) ** 2) / (sigma * Math.sqrt(2 * Math.PI));
}

function binomialPMF(k: number, n: number, p: number) {
    return binomCoeff(n, k) * Math.pow(p, k) * Math.pow(1 - p, n - k);
}

function poissonPMF(k: number, lambda: number) {
    // Use log space to avoid overflow
    let logP = k * Math.log(lambda) - lambda;
    for (let i = 1; i <= k; i++) logP -= Math.log(i);
    return Math.exp(logP);
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function CommonDistributionsPrimitive() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [activeDist, setActiveDist] = useState<DistType>('normal');
    const [overlayAll, setOverlayAll] = useState(false);

    // Parameter State
    const [params, setParams] = useState({
        mu: 0, sigma: 1,
        nBinom: 20, pBinom: 0.5,
        lambda: 5,
        uniformA: -2, uniformB: 2
    });

    const updateParam = (key: keyof typeof params, val: number) => {
        setParams(prev => ({ ...prev, [key]: val }));
    };

    const currentStats = useMemo(() => {
        switch (activeDist) {
            case 'normal':
                return { mean: params.mu, variance: params.sigma ** 2, skew: 0, support: "(-Γê₧, +Γê₧)" };
            case 'binomial':
                const bv = params.nBinom * params.pBinom * (1 - params.pBinom);
                return {
                    mean: params.nBinom * params.pBinom,
                    variance: bv,
                    skew: (1 - 2 * params.pBinom) / Math.sqrt(bv || 1),
                    support: `{0, ..., ${params.nBinom}}`
                };
            case 'poisson':
                return { mean: params.lambda, variance: params.lambda, skew: 1 / Math.sqrt(params.lambda), support: "{0, 1, 2, ...}" };
            case 'uniform':
                const range = params.uniformB - params.uniformA;
                return { mean: (params.uniformA + params.uniformB) / 2, variance: (range ** 2) / 12, skew: 0, support: `[${params.uniformA}, ${params.uniformB}]` };
            default:
                return { mean: 0, variance: 0, skew: 0, support: "" };
        }
    }, [activeDist, params]);

    const render = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        ctx.clearRect(0, 0, W, H);

        const distsToDraw: DistType[] = overlayAll ? ['normal', 'binomial', 'poisson', 'uniform'] : [activeDist];

        // Determine Axis Ranges
        let xMin = -5, xMax = 5, yMax = 0.5;

        if (overlayAll || activeDist === 'binomial' || activeDist === 'poisson') {
            xMax = Math.max(10, params.nBinom, params.lambda * 2.5);
            xMin = -2;
        }
        if (activeDist === 'uniform') {
            xMin = params.uniformA - 2;
            xMax = params.uniformB + 2;
        }

        const xSpan = xMax - xMin;
        const toCX = (x: number) => M.left + ((x - xMin) / xSpan) * CW;
        const toCY = (y: number) => M.top + CH - (y / yMax) * CH;

        // Grid System
        ctx.strokeStyle = "rgba(255, 255, 255, 0.03)";
        ctx.lineWidth = 1;
        [0.1, 0.2, 0.3, 0.4].forEach(y => {
            const py = toCY(y);
            ctx.beginPath(); ctx.moveTo(M.left, py); ctx.lineTo(M.left + CW, py); ctx.stroke();
        });

        // Axis Lines
        ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(M.left, M.top);
        ctx.lineTo(M.left, M.top + CH);
        ctx.lineTo(M.left + CW, M.top + CH);
        ctx.stroke();

        // X Ticks
        ctx.fillStyle = "rgba(255, 255, 255, 0.3)";
        ctx.font = "10px var(--font-jetbrains)";
        ctx.textAlign = "center";
        const xStep = xSpan > 20 ? 5 : 2;
        for (let x = Math.ceil(xMin); x <= Math.floor(xMax); x += xStep) {
            if (x === 0) continue;
            const cx = toCX(x);
            ctx.fillText(x.toString(), cx, M.top + CH + 20);
        }

        // Draw Distributions
        distsToDraw.forEach(d => {
            const color = COLORS[d];
            ctx.strokeStyle = color;
            ctx.fillStyle = color;
            ctx.lineWidth = 2.5;

            if (d === 'normal') {
                ctx.beginPath();
                for (let i = 0; i <= 200; i++) {
                    const x = xMin + (i / 200) * xSpan;
                    const y = normalPDF(x, params.mu, params.sigma);
                    i === 0 ? ctx.moveTo(toCX(x), toCY(y)) : ctx.lineTo(toCX(x), toCY(y));
                }
                ctx.stroke();
                if (!overlayAll) {
                    ctx.globalAlpha = 0.1;
                    ctx.lineTo(toCX(xMax), toCY(0));
                    ctx.lineTo(toCX(xMin), toCY(0));
                    ctx.fill();
                    ctx.globalAlpha = 1;
                }
            } else if (d === 'binomial') {
                const _barW = Math.max(2, (CW / xSpan) * 0.6);
                for (let k = 0; k <= params.nBinom; k++) {
                    const y = binomialPMF(k, params.nBinom, params.pBinom);
                    const cx = toCX(k);
                    const cy = toCY(y);
                    ctx.globalAlpha = overlayAll ? 0.6 : 1;
                    ctx.fillRect(cx - barW / 2, cy, barW, M.top + CH - cy);
                    ctx.globalAlpha = 1;
                }
            } else if (d === 'poisson') {
                const _barW = Math.max(2, (CW / xSpan) * 0.4);
                for (let k = 0; k <= xMax; k++) {
                    const y = poissonPMF(k, params.lambda);
                    const cx = toCX(k);
                    const cy = toCY(y);
                    ctx.save();
                    ctx.translate(cx, cy);
                    ctx.beginPath();
                    ctx.arc(0, 0, 3, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.restore();

                    ctx.beginPath();
                    ctx.moveTo(cx, cy);
                    ctx.lineTo(cx, M.top + CH);
                    ctx.lineWidth = 1;
                    ctx.globalAlpha = 0.4;
                    ctx.stroke();
                    ctx.globalAlpha = 1;
                }
            } else if (d === 'uniform') {
                const h = 1 / (params.uniformB - params.uniformA);
                const cxA = toCX(params.uniformA);
                const cxB = toCX(params.uniformB);
                const cyH = toCY(h);
                const cy0 = toCY(0);

                ctx.beginPath();
                ctx.moveTo(toCX(xMin), cy0);
                ctx.lineTo(cxA, cy0);
                ctx.lineTo(cxA, cyH);
                ctx.lineTo(cxB, cyH);
                ctx.lineTo(cxB, cy0);
                ctx.lineTo(toCX(xMax), cy0);
                ctx.stroke();

                if (!overlayAll) {
                    ctx.globalAlpha = 0.1;
                    ctx.fillRect(cxA, cyH, cxB - cxA, cy0 - cyH);
                    ctx.globalAlpha = 1;
                }
            }
        });

    }, [activeDist, overlayAll, params]);

    useEffect(() => { render(); }, [render]);

    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
