                    <span style={{ color: depth >= 6 ? "#f87171" : depth <= 1 ? "#fbbf24" : "#34d399" }}>
                        {depth <= 1 ? "Underfit" : depth >= 6 ? "Overfit ΓÇö memorising" : "Good split"}
                    </span>
