        ctx.strokeStyle = "rgba(255, 255, 255, 0.2)";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(PAD.left, PAD.top);
        ctx.lineTo(PAD.left, PAD.top + pH);
        ctx.lineTo(PAD.left + pW, PAD.top + pH);
        ctx.stroke();

        // Labels
        ctx.fillStyle = "rgba(255, 255, 255, 0.5)";
        ctx.font = "10px var(--font-jetbrains)";
