            ctx.fillText(v === 0 ? "╬╝" : `${v}╧â`, cx, PAD.top + pH + 20);
        });

        ctx.save();
        ctx.translate(20, PAD.top + pH / 2);
        ctx.rotate(-Math.PI / 2);
        ctx.fillText("Probability Density", 0, 0);
        ctx.restore();

    }, [samples, showCurve]);

    useEffect(() => { render(); }, [render]);

    const autoPlay = useCallback(() => {
