                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";
import React, { useState, useEffect, useRef } from "react";

const W = 520, H = 260;
export default function DuplicateDataPrimitive() {
    const cvs = useRef<HTMLCanvasElement>(null);
    const [dupRatio, setDupRatio] = useState(0);
    const [showLeak, setShowLeak] = useState(false);
    const BASE_A = 40, BASE_B = 40;
    const extraA = Math.round(BASE_A * dupRatio);
    const totalA = BASE_A + extraA, totalB = BASE_B, total = totalA + totalB;
    const pctA = ((totalA / total) * 100).toFixed(1), pctB = ((totalB / total) * 100).toFixed(1);
    const CLASS_A = "#60a5fa", CLASS_B = "#f472b6", DUP = "#fbbf24", LEAK = "#f87171", TRAIN = "#34d399", TEST = "#a78bfa";

    useEffect(() => {
        const canvas = cvs.current; if (!canvas) return;
        const ctx = canvas.getContext("2d")!;
        ctx.clearRect(0, 0, W, H); ctx.fillStyle = "#0d0e18"; ctx.fillRect(0, 0, W, H);
        const bW = 80, maxH = 160, PL = 60, PT = 30;
        ctx.strokeStyle = "#111827"; ctx.lineWidth = 1;
        for (let i = 0; i <= 4; i++) {
            const y = PT + i / 4 * maxH; ctx.beginPath(); ctx.moveTo(PL - 10, y); ctx.lineTo(PL + 300, y); ctx.stroke();
            ctx.fillStyle = "#374151"; ctx.font = "9px monospace"; ctx.textAlign = "right"; ctx.fillText(Math.round((1 - i / 4) * Math.max(totalA, totalB)).toString(), PL - 14, y + 4);
        }
        const aH = (totalA / Math.max(totalA, totalB)) * maxH, baseAH = (BASE_A / Math.max(totalA, BASE_B)) * maxH;
        const x1 = PL + 20;
        const gA = ctx.createLinearGradient(x1, PT + maxH - baseAH, x1, PT + maxH); gA.addColorStop(0, CLASS_A); gA.addColorStop(1, CLASS_A + "88");
        ctx.fillStyle = gA; ctx.fillRect(x1, PT + maxH - baseAH, bW, baseAH);
        if (extraA > 0) {
            const dH = aH - baseAH; ctx.fillStyle = DUP + "cc"; ctx.fillRect(x1, PT + maxH - aH, bW, dH);
            ctx.strokeStyle = DUP; ctx.lineWidth = 1.5; ctx.setLineDash([4, 3]); ctx.strokeRect(x1, PT + maxH - aH, bW, dH); ctx.setLineDash([]);
            ctx.fillStyle = DUP; ctx.font = "bold 10px monospace"; ctx.textAlign = "center"; ctx.fillText(`+${extraA} dupes`, x1 + bW / 2, PT + maxH - aH - 6);
        }
        const bH = (totalB / Math.max(totalA, totalB)) * maxH, x2 = PL + 160;
        const gB = ctx.createLinearGradient(x2, PT + maxH - bH, x2, PT + maxH); gB.addColorStop(0, CLASS_B); gB.addColorStop(1, CLASS_B + "88");
        ctx.fillStyle = gB; ctx.fillRect(x2, PT + maxH - bH, bW, bH);
        ctx.fillStyle = "#e2e8f0"; ctx.font = "11px monospace"; ctx.textAlign = "center";
        ctx.fillText(`Class A  ${pctA}%`, x1 + bW / 2, PT + maxH + 18); ctx.fillText(`Class B  ${pctB}%`, x2 + bW / 2, PT + maxH + 18);
        ctx.fillStyle = CLASS_A; ctx.fillText(`n=${totalA}`, x1 + bW / 2, PT + maxH - aH - (extraA > 0 ? 22 : 6));
        ctx.fillStyle = CLASS_B; ctx.fillText(`n=${totalB}`, x2 + bW / 2, PT + maxH - bH - 6);
        if (showLeak) {
            const lx = PL + 290, ly = PT + 10, lw = 160, lh = maxH;
            ctx.fillStyle = TRAIN + "22"; ctx.fillRect(lx, ly, lw * .7, lh); ctx.strokeStyle = TRAIN; ctx.lineWidth = 1.5; ctx.strokeRect(lx, ly, lw * .7, lh);
            ctx.fillStyle = TRAIN; ctx.font = "10px monospace"; ctx.textAlign = "center"; ctx.fillText("TRAIN", lx + lw * .35, ly + lh / 2);
            ctx.fillStyle = TEST + "22"; ctx.fillRect(lx + lw * .7 + 4, ly, lw * .3 - 4, lh); ctx.strokeStyle = TEST; ctx.lineWidth = 1.5; ctx.strokeRect(lx + lw * .7 + 4, ly, lw * .3 - 4, lh);
            ctx.fillStyle = TEST; ctx.fillText("TEST", lx + lw * .85, ly + lh / 2);
            if (dupRatio > 0) {
                const mX = lx + lw * .7 + 2;
                ctx.beginPath(); ctx.moveTo(lx + lw * .5, ly + lh * .4); ctx.bezierCurveTo(mX + 10, ly + lh * .3, mX + 10, ly + lh * .6, lx + lw * .8, ly + lh * .6);
                ctx.strokeStyle = LEAK; ctx.lineWidth = 2; ctx.shadowColor = LEAK; ctx.shadowBlur = 8; ctx.stroke(); ctx.shadowBlur = 0;
                ctx.fillStyle = LEAK; ctx.font = "bold 9px monospace"; ctx.textAlign = "center";
                ctx.fillText("ΓÜá LEAK", mX + 15, ly + lh * .22); ctx.fillText("dupe in", mX + 15, ly + lh * .22 + 12); ctx.fillText("train", mX + 15, ly + lh * .22 + 24);
            }
        }
    }, [dupRatio, showLeak, totalA, extraA]);

    const iColor = dupRatio > 0.5 ? "#f87171" : "rgba(255,255,255,0.3)";
    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-5 select-none">
            <div className="space-y-1">
                <h3 className="text-sm font-bold text-muted uppercase tracking-wider flex items-center gap-2">
                    <span className="material-symbols-outlined text-base">content_copy</span>Duplicate Data
                </h3>
                <p className="text-xs text-muted/60">Duplicates are Echoes ΓÇö they make the model hear whatever was shouted twice, skewing class balance and inflating test scores.</p>
            </div>
            <div className="rounded-xl overflow-hidden border border-border">
                <canvas ref={cvs} width={W} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
            </div>
            <div className="space-y-2">
                <div className="flex justify-between text-[11px]">
                    <span className="text-muted/50">Duplicate Ratio (Class A)</span>
                    <span style={{ color: dupRatio > 0 ? "#fbbf24" : "rgba(255,255,255,0.3)" }}>{Math.round(dupRatio * 100)}% extra copies</span>
                </div>
                <input type="range" min={0} max={2} step={0.05} value={dupRatio} onChange={e => setDupRatio(+e.target.value)} className="w-full cursor-pointer" style={{ accentColor: "#fbbf24" }} />
                <div className="flex justify-between text-[10px] text-muted/30"><span>Balanced</span><span>3├ù imbalanced</span></div>
            </div>
            <label className="flex items-center gap-2 text-[11px] cursor-pointer" style={{ color: showLeak ? "#f87171" : "rgba(255,255,255,0.3)" }}>
                <input type="checkbox" checked={showLeak} onChange={e => setShowLeak(e.target.checked)} style={{ accentColor: "#f87171" }} />
                Show train/test leakage risk
            </label>
            <div className="flex gap-4 text-[11px]">
                {[{ label: "Class A", val: `${totalA} (${pctA}%)`, color: "#60a5fa" }, { label: "Class B", val: `${totalB} (${pctB}%)`, color: "#f472b6" }, { label: "Imbalance", val: `${(totalA / totalB).toFixed(2)}:1`, color: iColor }].map(({ label, val, color }) => (
                    <div key={label} className="text-center"><div className="text-[9px] text-muted/30 mb-0.5">{label}</div><div className="font-bold" style={{ color }}>{val}</div></div>
                ))}
            </div>
            <div className="rounded-r-lg border-l-4 px-4 py-3 text-[11px] leading-relaxed" style={{ borderColor: "#fbbf24", background: "#fbbf240f", color: "rgba(255,255,255,0.5)" }}>
                <span className="text-amber-400">KEY RISKS: </span>(1) Class imbalance makes accuracy misleading. (2) Duplicates spanning train/test split artificially inflate test score. Always deduplicate <em>before</em> splitting!
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";

// ΓöÇΓöÇΓöÇ Constants & Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const CW = 720, CH = 460;
const SCALE = 70;

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function EigenvectorsPrimitive() {
    const [a, setA] = useState(2);
    const [b, setB] = useState(1);
    const [c, setC] = useState(0);
    const [d, setD] = useState(1);

    const canvasRef = useRef<HTMLCanvasElement>(null);

    const OX = CW / 2, OY = CH / 2;

    const stats = useMemo(() => {
        const trace = a + d;
        const det = a * d - b * c;
        const discriminant = trace * trace - 4 * det;

        let lambda1: number | null = null;
        let lambda2: number | null = null;

        if (discriminant >= 0) {
            lambda1 = (trace + Math.sqrt(discriminant)) / 2;
            lambda2 = (trace - Math.sqrt(discriminant)) / 2;
        }

        return { trace, det, discriminant, lambda1, lambda2 };
    }, [a, b, c, d]);

    const applyM = useCallback((v: { x: number, y: number }) => {
        return {
            x: a * v.x + b * v.y,
            y: c * v.x + d * v.y,
        };
    }, [a, b, c, d]);

    // ΓöÇΓöÇΓöÇ Drawing Logic ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const drawGrid = (ctx: CanvasRenderingContext2D) => {
        ctx.save();
        ctx.strokeStyle = "rgba(255, 255, 255, 0.05)";
        ctx.lineWidth = 1;

        for (let x = -6; x <= 6; x++) {
            ctx.beginPath();
            ctx.moveTo(OX + x * SCALE, 0);
            ctx.lineTo(OX + x * SCALE, CH);
            ctx.stroke();
        }

        for (let y = -6; y <= 6; y++) {
            ctx.beginPath();
            ctx.moveTo(0, OY - y * SCALE);
            ctx.lineTo(CW, OY - y * SCALE);
            ctx.stroke();
        }
        ctx.restore();
    };

    const drawTransformedGrid = (ctx: CanvasRenderingContext2D) => {
        ctx.save();
        ctx.strokeStyle = "hsla(var(--primary), 0.2)";
        ctx.lineWidth = 1.5;

        const range = 6;
        for (let x = -range; x <= range; x++) {
            const p1 = applyM({ x, y: -range });
            const p2 = applyM({ x, y: range });
            ctx.beginPath();
            ctx.moveTo(OX + p1.x * SCALE, OY - p1.y * SCALE);
            ctx.lineTo(OX + p2.x * SCALE, OY - p2.y * SCALE);
            ctx.stroke();
        }
        for (let y = -range; y <= range; y++) {
            const p1 = applyM({ x: -range, y });
            const p2 = applyM({ x: range, y });
            ctx.beginPath();
            ctx.moveTo(OX + p1.x * SCALE, OY - p1.y * SCALE);
            ctx.lineTo(OX + p2.x * SCALE, OY - p2.y * SCALE);
            ctx.stroke();
        }
        ctx.restore();
    };

    const drawEigenDirections = (ctx: CanvasRenderingContext2D) => {
        if (stats.discriminant < 0) return;

        const eigenvalues = [stats.lambda1, stats.lambda2];
        const colors = ["hsl(var(--rose-400))", "hsl(var(--emerald-400))"];

        ctx.save();
        eigenvalues.forEach((lambda, i) => {
            if (lambda === null) return;

            let v;
            if (Math.abs(b) > 0.0001) {
                v = { x: lambda - d, y: b };
            } else if (Math.abs(c) > 0.0001) {
                v = { x: c, y: lambda - a };
            } else {
                v = i === 0 ? { x: 1, y: 0 } : { x: 0, y: 1 };
            }

            const norm = Math.sqrt(v.x * v.x + v.y * v.y);
            if (norm < 0.0001) return;

            const unit = { x: v.x / norm, y: v.y / norm };
            const color = colors[i];

            // draw infinite-like line for eigenvector direction
            ctx.strokeStyle = color;
            ctx.setLineDash([5, 5]);
            ctx.lineWidth = 2;
            ctx.beginPath();
            const L = 10; // length multiplier
            ctx.moveTo(OX - unit.x * SCALE * L, OY + unit.y * SCALE * L);
            ctx.lineTo(OX + unit.x * SCALE * L, OY - unit.y * SCALE * L);
            ctx.stroke();

            // draw the unit vector and its transformation
            ctx.setLineDash([]);
            ctx.lineWidth = 4;

            const drawArrow = (from: { x: number, y: number }, to: { x: number, y: number }, col: string) => {
                const dx = to.x - from.x, dy = to.y - from.y;
                const len = Math.sqrt(dx * dx + dy * dy);
                ctx.strokeStyle = col; ctx.fillStyle = col;
                ctx.beginPath(); ctx.moveTo(from.x, from.y); ctx.lineTo(to.x - (dx / len) * 10, to.y - (dy / len) * 10); ctx.stroke();
                const angle = Math.atan2(dy, dx);
                ctx.beginPath(); ctx.moveTo(to.x, to.y);
                ctx.lineTo(to.x - 10 * Math.cos(angle - 0.4), to.y - 10 * Math.sin(angle - 0.4));
                ctx.lineTo(to.x - 10 * Math.cos(angle + 0.4), to.y - 10 * Math.sin(angle + 0.4));
                ctx.closePath(); ctx.fill();
            };

            const origin = { x: OX, y: OY };
            const uPx = { x: OX + unit.x * SCALE, y: OY - unit.y * SCALE };
            const stretched = applyM(unit);
            const sPx = { x: OX + stretched.x * SCALE, y: OY - stretched.y * SCALE };

            // Basis unit vector
            drawArrow(origin, uPx, "white");
            // Transformed vector (should be along the same line)
            drawArrow(origin, sPx, color);

            ctx.font = "bold 12px var(--font-jetbrains)";
            ctx.fillStyle = color;
            ctx.fillText(`v${i + 1}`, uPx.x + 8, uPx.y - 8);
        });
        ctx.restore();
    };

    const render = useCallback(() => {
        const ctx = canvasRef.current?.getContext("2d");
        if (!ctx) return;

        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = "hsl(var(--surface))";
        ctx.fillRect(0, 0, CW, CH);

        drawGrid(ctx);
        drawTransformedGrid(ctx);
        drawEigenDirections(ctx);

        // Origin
        ctx.fillStyle = "white";
        ctx.beginPath(); ctx.arc(OX, OY, 4, 0, Math.PI * 2); ctx.fill();
    }, [a, b, c, d, stats, drawEigenDirections]);

    useEffect(() => {
        render();
    }, [render]);

    const geometricMeaning = () => {
        if (stats.discriminant < 0)
            return "Rotation-like behavior (no real invariant directions).";

        if (stats.det < 0)
            return "Orientation flip (reflection component present).";

        if (Math.abs((stats.lambda1 ?? 0) - (stats.lambda2 ?? 0)) < 0.0001)
            return "Repeated eigenvalue ΓÇö possible shear or defective matrix.";

        return "Two invariant directions ΓÇö pure stretch along eigenvectors.";
    };

    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-6 select-none">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between gap-6">
                <div className="space-y-4">
                    <div className="space-y-1">
                        <h3 className="text-sm font-bold text-muted uppercase tracking-wider flex items-center gap-2">
                            <span className="material-symbols-outlined text-base">psychology</span>
                            Eigenvalues & Eigenvectors
                        </h3>
                        <p className="text-xs text-muted/60 max-w-lg">
                            Invariant directions of a linear transformation. When a matrix acts on them, they stay on their own span ΓÇö only scaling by ╬╗.
                        </p>
                    </div>

                    <div className="flex gap-4">
                        <div className="bg-black/40 border border-border rounded-xl px-4 py-3 min-w-[200px]">
                            <span className="text-[9px] uppercase font-bold text-muted/40 block mb-1">Characteristic Eq Roots (╬╗)</span>
                            <span className="text-xl font-black text-primary">
                                {stats.discriminant < 0 ? (
                                    <span className="text-rose-400">Complex Pair</span>
                                ) : (
                                    <>╬╗Γéü: {stats.lambda1?.toFixed(2)} | ╬╗Γéé: {stats.lambda2?.toFixed(2)}</>
                                )}
                            </span>
                        </div>
                    </div>
                </div>

                {/* Matrix Controls */}
                <div className="grid grid-cols-2 gap-3 bg-black/40 border border-border rounded-xl p-4 min-w-[240px]">
                    {[
                        { label: "a", value: a, setter: setA },
                        { label: "b", value: b, setter: setB },
                        { label: "c", value: c, setter: setC },
                        { label: "d", value: d, setter: setD }
                    ].map((item, idx) => (
                        <div key={idx} className="space-y-1">
                            <div className="flex justify-between text-[10px] font-bold text-muted/60 uppercase">
                                <span>{item.label}</span>
                                <span>{item.value.toFixed(1)}</span>
                            </div>
                            <input
                                type="range" min="-3" max="3" step="0.1" value={item.value}
                                onChange={e => item.setter(parseFloat(e.target.value))}
                                className="w-full accent-primary"
                            />
                        </div>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                {/* Canvas Area */}
                <div className="lg:col-span-8 bg-black/60 border border-border rounded-xl overflow-hidden relative group">
                    <div className="absolute top-3 left-4 flex gap-4 text-[9px] font-bold text-muted/40 uppercase tracking-widest z-10">
                        <span>Invariant Direction Lab</span>
                        <span className="text-primary italic">{geometricMeaning()}</span>
                    </div>
                    <canvas
                        ref={canvasRef} width={CW} height={CH}
                        className="w-full h-auto cursor-crosshair"
                    />
                </div>

                {/* Right Info Panel */}
                <div className="lg:col-span-4 space-y-4">
                    <div className="bg-black/40 border border-border rounded-xl p-5 space-y-4">
                        <div className="text-[10px] font-black text-muted uppercase tracking-widest border-b border-border pb-2">Matrix Properties</div>
                        <div className="space-y-3">
                            <div className="flex justify-between items-center bg-surface2/30 p-2 rounded border border-border/40 text-xs">
