        function rToY(r: number) { return rPAD.t + rH / 2 - (r / maxR) * (rH / 2 - 4); }

        // Zero line
        ctx.beginPath(); ctx.moveTo(rPAD.l, rPAD.t + rH / 2); ctx.lineTo(rPAD.l + rW, rPAD.t + rH / 2);
        ctx.strokeStyle = "#334155"; ctx.lineWidth = 1.5; ctx.stroke();

        // Residual bars
        const color = round === 0 ? "#94a3b8" : ROUND_COLORS[round - 1];
        DATA.forEach((d, i) => {
            const r = residuals[i];
            const cx = rToX(d.x), cy0 = rPAD.t + rH / 2, cy1 = rToY(r);
            ctx.beginPath(); ctx.moveTo(cx, cy0); ctx.lineTo(cx, cy1);
            ctx.strokeStyle = r > 0 ? "#34d39988" : "#f8717188"; ctx.lineWidth = 2; ctx.stroke();
            ctx.beginPath(); ctx.arc(cx, cy1, 3, 0, Math.PI * 2);
            ctx.fillStyle = r > 0 ? "#34d399" : "#f87171"; ctx.fill();
        });

        // Axes labels
        ctx.fillStyle = THEME.dim; ctx.font = "9px monospace"; ctx.textAlign = "center";
        ctx.fillText("residuals", rPAD.l + rW / 2, RH - 4);
        ctx.textAlign = "right";
        [+maxR.toFixed(1), 0, -maxR.toFixed(1)].forEach((v, i) => {
            ctx.fillText(v.toString(), rPAD.l - 4, rPAD.t + (i / 2) * rH + 4);
        });
        ctx.fillStyle = color; ctx.font = "bold 9px monospace"; ctx.textAlign = "right";
        ctx.fillText(`RMSE ${currentRMSE}`, rPAD.l + rW - 2, rPAD.t + 12);
    }

    const autoPlay = () => {
        setAnimating(true); setRound(0);
        let r = 0;
        function step() {
            r++; setRound(r);
            if (r < ROUNDS.length) { timerRef.current = setTimeout(step, 700); }
            else setAnimating(false);
        }
        timerRef.current = setTimeout(step, 500);
    };

    useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);

    return (
        <div style={{ fontFamily: "'SF Mono','Fira Code',monospace", background: THEME.bg, padding: "24px 20px", color: THEME.text, borderRadius: "8px", border: `1px solid ${THEME.border}`, maxWidth: 800, margin: "0 auto" }}>
            <div style={{ textAlign: "center", marginBottom: "16px" }}>
                <div style={{ fontSize: "10px", letterSpacing: "4px", color: THEME.dim, marginBottom: "6px" }}>SUBJECT IV ┬╖ REGRESSION ┬╖ ┬º52</div>
                <h1 style={{ fontSize: "24px", fontWeight: 700, margin: "0 0 4px" }}>Gradient Boosting</h1>
                <p style={{ fontSize: "12px", color: THEME.dim, margin: 0, fontStyle: "italic" }}>
                    "Each new tree ignores what we got right ΓÇö it obsessively fixes the remaining errors."
                </p>
            </div>

            <div style={{ display: "flex", gap: "12px", flexWrap: "wrap", justifyContent: "center" }}>
                <div>
                    <div style={{ fontSize: "10px", color: THEME.dim, letterSpacing: "2px", marginBottom: "6px", textAlign: "center" }}>ENSEMBLE PREDICTION</div>
                    <div style={{ border: `1px solid ${THEME.border}`, borderRadius: "8px", overflow: "hidden" }}>
                        <canvas ref={mainRef} width={W} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
                    </div>
                </div>
                <div>
                    <div style={{ fontSize: "10px", color: THEME.dim, letterSpacing: "2px", marginBottom: "6px", textAlign: "center" }}>RESIDUALS (WHAT'S LEFT TO FIX)</div>
                    <div style={{ border: `1px solid ${THEME.border}`, borderRadius: "8px", overflow: "hidden" }}>
                        <canvas ref={residRef} width={220} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
                    </div>
                </div>
            </div>

            {/* Round stepper */}
            <div style={{ display: "flex", gap: "6px", marginTop: "14px", flexWrap: "wrap", justifyContent: "center" }}>
                <button onClick={() => { setRound(0); setAnimating(false); if (timerRef.current) clearTimeout(timerRef.current); }}
                    style={{ padding: "6px 12px", border: `1px solid ${THEME.border}`, borderRadius: "4px", background: round === 0 ? "#ffffff22" : "transparent", color: "#94a3b8", fontSize: "10px", fontFamily: "inherit", cursor: "pointer" }}>
                    Baseline
                </button>
                {ROUNDS.map((_, i) => (
                    <button key={i} onClick={() => { setRound(i + 1); setAnimating(false); if (timerRef.current) clearTimeout(timerRef.current); }}
                        style={{ padding: "6px 12px", border: `1.5px solid ${round === i + 1 ? ROUND_COLORS[i] : THEME.border}`, borderRadius: "4px", background: round === i + 1 ? ROUND_COLORS[i] + "22" : "transparent", color: round === i + 1 ? ROUND_COLORS[i] : THEME.dim, fontSize: "10px", fontFamily: "inherit", cursor: "pointer", transition: "all 0.2s" }}>
                        +{i + 1}
                    </button>
                ))}
            </div>

            <div style={{ display: "flex", gap: "10px", marginTop: "12px", justifyContent: "center" }}>
                <button onClick={autoPlay} disabled={animating}
                    style={{ padding: "8px 22px", border: "none", borderRadius: "4px", background: animating ? THEME.dim : "#fbbf24", color: "#000", fontSize: "12px", fontFamily: "inherit", fontWeight: 700, cursor: animating ? "not-allowed" : "pointer", letterSpacing: "1px" }}>
                    {animating ? "BOOSTINGΓÇª" : "Γû╢ AUTO BOOST"}
                </button>
                <button onClick={() => { setRound(0); setAnimating(false); if (timerRef.current) clearTimeout(timerRef.current); }}
                    style={{ padding: "8px 14px", border: `1px solid ${THEME.border}`, borderRadius: "4px", background: "transparent", color: THEME.dim, fontSize: "12px", fontFamily: "inherit", cursor: "pointer" }}>Γå║</button>
            </div>

            <div style={{ marginTop: "14px", padding: "10px 18px", borderLeft: "3px solid #fbbf24", background: "#fbbf240f", maxWidth: 500, fontSize: "11px", color: THEME.dim, lineHeight: 1.8, borderRadius: "0 4px 4px 0", margin: "14px auto 0" }}>
                <span style={{ color: "#fbbf24" }}>// MECHANISM:</span> Each round fits a shallow tree to the <em>residuals</em> (errors) from all previous rounds, then adds it multiplied by the learning rate ({LR}). The residual plot should shrink toward zero as rounds increase.
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { GradientChainRuleConfig } from "@/adapters/visual-types";

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const W = 720, H = 360;
const PAD = { top: 40, right: 40, bottom: 55, left: 70 };
const pW = W - PAD.left - PAD.right;
const pH = H - PAD.top - PAD.bottom;
const X_MIN = -3.5, X_MAX = 3.5;
const Y_MIN = -0.2, Y_MAX = 3.2;

// ΓöÇΓöÇΓöÇ Math ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Composite: h(x) = f(g(x)) where g(x) = x┬▓ΓêÆ1, f(u) = 0.8┬╖sin(u)
const gFn = (x: number) => x * x - 1;
const gPrime = (x: number) => 2 * x;
const fFn = (u: number) => Math.sin(u) * 0.8;
const fPrime = (u: number) => Math.cos(u) * 0.8;
const hFn = (x: number) => fFn(gFn(x)) + 2;          // shifted up for visibility
const hPrime = (x: number) => fPrime(gFn(x)) * gPrime(x); // chain rule

// ΓöÇΓöÇΓöÇ Canvas helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const toCanvasX = (x: number) => PAD.left + ((x - X_MIN) / (X_MAX - X_MIN)) * pW;
const toCanvasY = (y: number) => PAD.top + pH - ((y - Y_MIN) / (Y_MAX - Y_MIN)) * pH;
const fromCanvasX = (cx: number) => X_MIN + ((cx - PAD.left) / pW) * (X_MAX - X_MIN);

// ΓöÇΓöÇΓöÇ Props ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
interface Props {
    config?: GradientChainRuleConfig;
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function GradientChainRulePrimitive({ config: _config }: Props) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [xVal, setXVal] = useState(1.5);
    const [dragging, setDragging] = useState(false);

    // Derived values
    const y = hFn(xVal);
    const slope = hPrime(xVal);
    const innerV = gFn(xVal);
    const dfdg = fPrime(innerV);
    const dgdx = gPrime(xVal);

    // ΓöÇΓöÇΓöÇ Draw ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const draw = useCallback(() => {
        const ctx = canvasRef.current?.getContext("2d");
        if (!ctx) return;

        ctx.clearRect(0, 0, W, H);
        ctx.fillStyle = "hsl(var(--surface))";
        ctx.fillRect(0, 0, W, H);

        // ΓöÇΓöÇ Grid ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        ctx.strokeStyle = "rgba(255,255,255,0.03)";
        ctx.lineWidth = 1;
        for (let i = 0; i <= 5; i++) {
            const cy = PAD.top + (i / 5) * pH;
            ctx.beginPath(); ctx.moveTo(PAD.left, cy); ctx.lineTo(PAD.left + pW, cy); ctx.stroke();
        }

        const steps = 250;

        // ΓöÇΓöÇ Filled area under h(x) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        ctx.beginPath();
        for (let i = 0; i <= steps; i++) {
            const xi = X_MIN + (i / steps) * (X_MAX - X_MIN);
            const px = toCanvasX(xi), py = toCanvasY(hFn(xi));
            i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
        }
        ctx.lineTo(toCanvasX(X_MAX), toCanvasY(Y_MIN));
        ctx.lineTo(toCanvasX(X_MIN), toCanvasY(Y_MIN));
        ctx.closePath();
        ctx.fillStyle = "hsla(var(--primary), 0.06)";
        ctx.fill();

        // ΓöÇΓöÇ Main curve h(x) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        ctx.beginPath();
        for (let i = 0; i <= steps; i++) {
            const xi = X_MIN + (i / steps) * (X_MAX - X_MIN);
            const px = toCanvasX(xi), py = toCanvasY(hFn(xi));
            i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
        }
        ctx.strokeStyle = "hsl(var(--primary))";
        ctx.lineWidth = 2.5;
        ctx.shadowColor = "hsl(var(--primary))";
        ctx.shadowBlur = 8;
        ctx.stroke();
        ctx.shadowBlur = 0;

        // ΓöÇΓöÇ Tangent line ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        const cx0 = toCanvasX(xVal), cy0 = toCanvasY(y);
        const tanLen = 1.2;
        ctx.beginPath();
        ctx.moveTo(toCanvasX(xVal - tanLen), toCanvasY(y + slope * (-tanLen)));
        ctx.lineTo(toCanvasX(xVal + tanLen), toCanvasY(y + slope * tanLen));
        ctx.strokeStyle = "hsl(var(--amber-400, 251 191 36))";
        ctx.lineWidth = 2;
        ctx.setLineDash([5, 4]);
        ctx.stroke();
        ctx.setLineDash([]);

        // ΓöÇΓöÇ Gradient (downhill) arrow ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        const downDir = -Math.sign(slope);
        const arrowMag = Math.min(Math.abs(slope) * 0.3, 0.9);
        const arrowEndX = toCanvasX(xVal + downDir * arrowMag);
        const arrowColor = slope > 0 ? "hsl(var(--emerald-400))" : "hsl(var(--rose-400))";

        if (Math.abs(slope) > 0.05) {
            ctx.beginPath();
            ctx.moveTo(cx0, cy0);
            ctx.lineTo(arrowEndX, cy0);
            ctx.strokeStyle = arrowColor;
            ctx.lineWidth = 2.5;
            ctx.stroke();
            // Arrowhead
            const hd = downDir > 0 ? 1 : -1;
            ctx.beginPath();
            ctx.moveTo(arrowEndX, cy0);
            ctx.lineTo(arrowEndX - hd * 9, cy0 - 5);
            ctx.lineTo(arrowEndX - hd * 9, cy0 + 5);
            ctx.closePath();
            ctx.fillStyle = arrowColor;
            ctx.fill();
        }

        // ΓöÇΓöÇ Ball ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        ctx.beginPath();
        ctx.arc(cx0, cy0, 9, 0, Math.PI * 2);
        ctx.fillStyle = "white";
        ctx.shadowColor = "hsl(var(--primary))";
        ctx.shadowBlur = 18;
        ctx.fill();
        ctx.shadowBlur = 0;
        ctx.strokeStyle = "hsl(var(--primary))";
        ctx.lineWidth = 2;
        ctx.stroke();

        // Drop line
        ctx.beginPath();
        ctx.moveTo(cx0, cy0);
        ctx.lineTo(cx0, toCanvasY(0));
        ctx.strokeStyle = "rgba(255,255,255,0.12)";
        ctx.lineWidth = 1;
        ctx.setLineDash([3, 3]);
        ctx.stroke();
        ctx.setLineDash([]);

        // ΓöÇΓöÇ Axes ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        ctx.strokeStyle = "rgba(255,255,255,0.12)";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(PAD.left, PAD.top);
        ctx.lineTo(PAD.left, PAD.top + pH);
        ctx.lineTo(PAD.left + pW, PAD.top + pH);
        ctx.stroke();

        // X-axis labels
        ctx.fillStyle = "rgba(255,255,255,0.25)";
        ctx.font = "10px var(--font-jetbrains)";
        ctx.textAlign = "center";
        [-3, -2, -1, 0, 1, 2, 3].forEach(v => {
            ctx.fillText(String(v), toCanvasX(v), PAD.top + pH + 18);
        });
        ctx.fillText("x", PAD.left + pW / 2, H - 6);

        ctx.save();
        ctx.translate(14, PAD.top + pH / 2);
        ctx.rotate(-Math.PI / 2);
        ctx.fillText("h(x)", 0, 0);
        ctx.restore();

        // Slope readout
        ctx.textAlign = "right";
        ctx.fillStyle = "rgba(251,191,36,0.8)";
        ctx.font = "bold 10px var(--font-jetbrains)";
        ctx.fillText(`slope = ${slope.toFixed(3)}`, W - PAD.right + 10, PAD.top + 18);
    }, [xVal, y, slope]);

    useEffect(() => { draw(); }, [draw]);

    // ΓöÇΓöÇΓöÇ Drag handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const handleMouseDown = useCallback((e: React.MouseEvent) => {
        const rect = canvasRef.current?.getBoundingClientRect();
        if (!rect) return;
        const cx = e.clientX - rect.left;
