                </button>
            </div>

            <div className="p-4 bg-primary/5 border border-primary/10 rounded-lg">
                <p className="text-xs text-muted leading-relaxed italic text-center">
                    Notice how <span className="text-foreground font-semibold">Adam</span> adjusts its step size for the curvature, while <span className="text-foreground font-semibold">GD</span> remains rigid. High noise reveals the variance of Stochastic Gradient Descent.
                </p>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef, useCallback } from "react";

const W = 420, H = 360;
const PAD = { top: 20, right: 20, bottom: 36, left: 44 };
const pW = W - PAD.left - PAD.right;
const pH = H - PAD.top - PAD.bottom;

function randNorm(m = 0, s = 1) {
    let u = 0; while (!u) u = Math.random();
    return m + s * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random());
}

const CLASS_COLORS = ["#f472b8", "#60a5fa", "#34d399"];
const CENTERS = [{ x: 2.5, y: 7 }, { x: 7, y: 7 }, { x: 5, y: 2.5 }];
const DATA = CENTERS.flatMap((c, ci) =>
    Array.from({ length: 20 }, () => ({
        x: Math.max(0.3, Math.min(9.7, c.x + randNorm(0, 1.3))),
        y: Math.max(0.3, Math.min(9.7, c.y + randNorm(0, 1.3))),
        cls: ci,
    }))
);

function toX(x: number) { return PAD.left + (x / 10) * pW; }
function toY(y: number) { return PAD.top + pH - (y / 10) * pH; }

type Point = { x: number; y: number; cls: number };

function knnClassify(query: { x: number; y: number }, data: Point[], k: number) {
    const sorted = [...data].sort((a, b) =>
        Math.hypot(a.x - query.x, a.y - query.y) - Math.hypot(b.x - query.x, b.y - query.y));
    const neighbors = sorted.slice(0, k);
    const votes = [0, 0, 0];
    neighbors.forEach(n => votes[n.cls]++);
    return { cls: votes.indexOf(Math.max(...votes)), neighbors };
}

const GRID_RES = 35;
const THEME = { bg: "#08090d", surface: "#0d0e18", border: "#1a1b2c", text: "#e2e8f0", dim: "#374151" };

export default function KNNClassificationPrimitive() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [k, setK] = useState(5);
    const [query, setQuery] = useState({ x: 5, y: 5 });

    const { cls: predCls, neighbors } = knnClassify(query, DATA, k);
    const furthest = neighbors.reduce((m, n) => Math.max(m, Math.hypot(n.x - query.x, n.y - query.y)), 0);
    const accuracy = DATA.filter(d => knnClassify(d, DATA.filter(dd => dd !== d), k).cls === d.cls).length / DATA.length;

    // Build color grid
    const grid: { gx: number; gy: number; cls: number }[] = [];
    for (let gy = 0; gy < GRID_RES; gy++)
        for (let gx = 0; gx < GRID_RES; gx++) {
            const x = (gx + 0.5) / GRID_RES * 10, y = (gy + 0.5) / GRID_RES * 10;
            grid.push({ gx, gy, cls: knnClassify({ x, y }, DATA, k).cls });
        }

    useEffect(() => { draw(); }, [k, query]);

    function draw() {
        const canvas = canvasRef.current; if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        ctx.clearRect(0, 0, W, H); ctx.fillStyle = THEME.surface; ctx.fillRect(0, 0, W, H);

        const cellW = pW / GRID_RES, cellH = pH / GRID_RES;
        grid.forEach(({ gx, gy, cls }) => {
            ctx.fillStyle = CLASS_COLORS[cls] + "25";
            ctx.fillRect(PAD.left + gx * cellW, PAD.top + (GRID_RES - 1 - gy) * cellH, cellW + 1, cellH + 1);
        });

        // Query radius circle
        const rpx = (furthest / 10) * pW;
        ctx.beginPath(); ctx.arc(toX(query.x), toY(query.y), rpx, 0, Math.PI * 2);
        ctx.fillStyle = CLASS_COLORS[predCls] + "12"; ctx.fill();
        ctx.strokeStyle = CLASS_COLORS[predCls] + "55"; ctx.lineWidth = 1.5;
        ctx.setLineDash([4, 3]); ctx.stroke(); ctx.setLineDash([]);

        // Connection lines to neighbors
        neighbors.forEach(n => {
            ctx.beginPath(); ctx.moveTo(toX(query.x), toY(query.y));
            ctx.lineTo(toX(n.x), toY(n.y));
            ctx.strokeStyle = CLASS_COLORS[n.cls] + "66"; ctx.lineWidth = 1.2; ctx.stroke();
        });

        // Data points
        DATA.forEach(d => {
            const isNeighbor = neighbors.some(n => n === d);
            ctx.beginPath(); ctx.arc(toX(d.x), toY(d.y), isNeighbor ? 7 : 5, 0, Math.PI * 2);
            ctx.fillStyle = CLASS_COLORS[d.cls];
            ctx.globalAlpha = isNeighbor ? 1 : 0.55;
            if (isNeighbor) { ctx.shadowColor = CLASS_COLORS[d.cls]; ctx.shadowBlur = 12; }
            ctx.fill(); ctx.shadowBlur = 0; ctx.globalAlpha = 1;
            if (isNeighbor) { ctx.strokeStyle = "#fff"; ctx.lineWidth = 1.5; ctx.stroke(); }
        });

        // Vote tally bar
        const votes = [0, 0, 0];
        neighbors.forEach(n => votes[n.cls]++);
        const bx = PAD.left + pW - 60, by = PAD.top + 8;
        votes.forEach((v, ci) => {
            const bh = (v / k) * 40;
            ctx.fillStyle = CLASS_COLORS[ci] + "cc";
            ctx.fillRect(bx + ci * 22, by + 40 - bh, 16, bh);
            ctx.fillStyle = CLASS_COLORS[ci]; ctx.font = "bold 9px monospace"; ctx.textAlign = "center";
            ctx.fillText(v.toString(), bx + ci * 22 + 8, by + 40 - bh - 3);
        });
        ctx.fillStyle = THEME.dim; ctx.font = "8px monospace"; ctx.textAlign = "left";
        ctx.fillText("votes", bx, by + 52);

        // Query point
        const qx = toX(query.x), qy = toY(query.y);
        ctx.beginPath(); ctx.arc(qx, qy, 10, 0, Math.PI * 2);
        ctx.fillStyle = "#fff"; ctx.shadowColor = CLASS_COLORS[predCls]; ctx.shadowBlur = 20; ctx.fill(); ctx.shadowBlur = 0;
        ctx.strokeStyle = CLASS_COLORS[predCls]; ctx.lineWidth = 3; ctx.stroke();
        ctx.fillStyle = CLASS_COLORS[predCls]; ctx.font = "bold 8px monospace"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("?", qx, qy); ctx.textBaseline = "alphabetic";

        // Axes
        ctx.strokeStyle = "#252535"; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(PAD.left, PAD.top); ctx.lineTo(PAD.left, PAD.top + pH);
        ctx.lineTo(PAD.left + pW, PAD.top + pH); ctx.stroke();
        ctx.fillStyle = THEME.dim; ctx.font = "10px monospace"; ctx.textAlign = "center";
        ctx.fillText("featureΓéü ΓåÆ", PAD.left + pW / 2, H - 4);

        ctx.fillStyle = CLASS_COLORS[predCls]; ctx.font = "bold 10px monospace"; ctx.textAlign = "left";
        ctx.fillText(`ΓåÆ Class ${predCls} (k=${k})  acc=${(accuracy * 100).toFixed(0)}%`, PAD.left + 4, PAD.top + 14);
    }

    const handleMove = useCallback((e: React.MouseEvent) => {
        const canvas = canvasRef.current; if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const scaleX = W / rect.width;
        const scaleY = H / rect.height;
        const cx = (e.clientX - rect.left) * scaleX;
        const cy = (e.clientY - rect.top) * scaleY;
        if (cx >= PAD.left && cx <= PAD.left + pW && cy >= PAD.top && cy <= PAD.top + pH) {
            setQuery({
                x: +(cx - PAD.left) / pW * 10,
                y: +(PAD.top + pH - cy) / pH * 10,
            });
        }
    }, []);

    return (
        <div style={{ fontFamily: "'SF Mono','Fira Code',monospace", background: THEME.bg, padding: "24px 20px", color: THEME.text, borderRadius: "8px", border: `1px solid ${THEME.border}`, maxWidth: 800, margin: "0 auto" }}>
            <div style={{ textAlign: "center", marginBottom: "16px" }}>
                <div style={{ fontSize: "10px", letterSpacing: "4px", color: THEME.dim, marginBottom: "6px" }}>SUBJECT IV ┬╖ CLASSIFICATION ┬╖ ┬º61</div>
                <h1 style={{ fontSize: "24px", fontWeight: 700, margin: "0 0 4px" }}>KNN Classification</h1>
                <p style={{ fontSize: "12px", color: THEME.dim, margin: 0, fontStyle: "italic" }}>
                    "KNN is Democratic ΓÇö it takes a vote among your nearest neighbours, and majority wins."
                </p>
            </div>

            <div style={{ border: `1px solid ${CLASS_COLORS[predCls]}44`, borderRadius: "8px", overflow: "hidden", cursor: "crosshair", transition: "border-color 0.3s", background: THEME.surface, display: "flex", justifyContent: "center" }}
                onMouseMove={handleMove}>
                <canvas ref={canvasRef} width={W} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
            </div>

            <div style={{ marginTop: "8px", fontSize: "11px", color: "#fbbf24", textAlign: "center" }}>ΓåÉ MOVE MOUSE over the plot to query any point ΓåÆ</div>

            <div style={{ width: "100%", maxWidth: 400, marginTop: "12px", margin: "12px auto 0" }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "11px", color: THEME.dim, marginBottom: "6px" }}>
                    <span>k ΓÇö neighbours to consult</span>
                    <span style={{ color: CLASS_COLORS[predCls] }}>k = {k}</span>
                </div>
                <input type="range" min={1} max={20} step={1} value={k}
                    onChange={e => setK(+e.target.value)}
                    style={{ width: "100%", accentColor: "#94a3b8", cursor: "pointer" }} />
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "10px", color: THEME.dim, marginTop: "4px" }}>
                    <span>k=1 (jagged boundary)</span><span>k=20 (smooth, possibly underfit)</span>
                </div>
            </div>

            <div style={{ marginTop: "14px", padding: "10px 18px", borderLeft: `3px solid ${CLASS_COLORS[predCls]}`, background: CLASS_COLORS[predCls] + "0f", maxWidth: 440, fontSize: "11px", color: THEME.dim, lineHeight: 1.8, borderRadius: "0 4px 4px 0", margin: "14px auto 0" }}>
                <span style={{ color: CLASS_COLORS[predCls] }}>// INSIGHT:</span> The dashed circle shows the search radius. Bright glowing points are the k neighbours voting. Mini bar chart (top-right) shows the vote split. Odd k prevents ties.
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useRef, useCallback } from "react";

const W = 540, H = 320;
const PAD = { top: 28, right: 24, bottom: 44, left: 54 };
const pW = W - PAD.left - PAD.right;
const pH = H - PAD.top - PAD.bottom;

function randNorm(m = 0, s = 1) {
    let u = 0; while (!u) u = Math.random();
    return m + s * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random());
}

const trueF = (x: number) => Math.sin(x * 0.9) * 2.5 + x * 0.4 + 3;
const DATA = Array.from({ length: 35 }, (_, i) => {
    const x = 0.4 + i * 0.26;
    return { x: +x.toFixed(3), y: +(trueF(x) + randNorm(0, 0.8)).toFixed(3) };
});

const X_MIN = 0, X_MAX = 10, Y_MIN = 0, Y_MAX = 12;
function toX(x: number) { return PAD.left + ((x - X_MIN) / (X_MAX - X_MIN)) * pW; }
function toY(y: number) { return PAD.top + pH - ((y - Y_MIN) / (Y_MAX - Y_MIN)) * pH; }
function fromCanvasX(cx: number) { return X_MIN + ((cx - PAD.left) / pW) * (X_MAX - X_MIN); }

function knnPredict(query: number, data: typeof DATA, k: number) {
    const sorted = [...data].sort((a, b) => Math.abs(a.x - query) - Math.abs(b.x - query));
    const neighbors = sorted.slice(0, k);
    const pred = neighbors.reduce((s, d) => s + d.y, 0) / k;
    return { pred, neighbors };
}

function buildKNNCurve(data: typeof DATA, k: number) {
    return Array.from({ length: 200 }, (_, i) => {
        const x = X_MIN + (i / 199) * X_MAX;
        return { x, y: knnPredict(x, data, k).pred };
    });
}

const THEME = { bg: "#08090d", surface: "#0d0e18", border: "#1a1b2c", text: "#e2e8f0", dim: "#374151", grid: "#111827" };
const K_COLORS: Record<number, string> = { 1: "#f87171", 2: "#f87171", 3: "#fbbf24", 5: "#34d399", 7: "#60a5fa", 10: "#a78bfa", 15: "#a78bfa" };

export default function KNNRegressionPrimitive() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [k, setK] = useState(5);
    const [queryX, setQueryX] = useState(5.0);

    const { pred, neighbors } = knnPredict(queryX, DATA, k);
    const curve = buildKNNCurve(DATA, k);
    const color = K_COLORS[Math.min(15, k)] || "#60a5fa";

    useEffect(() => { draw(); }, [k, queryX]);

    function draw() {
        const canvas = canvasRef.current; if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        ctx.clearRect(0, 0, W, H); ctx.fillStyle = THEME.surface; ctx.fillRect(0, 0, W, H);

        // Grid
        ctx.strokeStyle = THEME.grid; ctx.lineWidth = 1;
        for (let i = 0; i <= 4; i++) {
            const y = PAD.top + (i / 4) * pH;
            ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + pW, y); ctx.stroke();
        }

        // KNN curve
        ctx.beginPath();
        curve.forEach(({ x, y }, i) => {
            const cx = toX(x), cy = toY(y);
            if (cy < PAD.top - 5 || cy > PAD.top + pH + 5) { return; }
            if (i === 0) ctx.moveTo(cx, cy); else ctx.lineTo(cx, cy);
        });
        ctx.strokeStyle = color; ctx.lineWidth = 2;
        ctx.shadowColor = color; ctx.shadowBlur = 5; ctx.stroke(); ctx.shadowBlur = 0;

        // Neighbor connection lines
        neighbors.forEach(n => {
            ctx.beginPath();
            ctx.moveTo(toX(queryX), toY(pred));
            ctx.lineTo(toX(n.x), toY(n.y));
            ctx.strokeStyle = color + "55"; ctx.lineWidth = 1.5; ctx.stroke();
        });

        // Query region highlight
        const furthest = neighbors.reduce((m, n) => Math.max(m, Math.abs(n.x - queryX)), 0);
        const rx1 = toX(queryX - furthest), rx2 = toX(queryX + furthest);
        ctx.fillStyle = color + "12";
        ctx.fillRect(rx1, PAD.top, rx2 - rx1, pH);
        ctx.strokeStyle = color + "33"; ctx.lineWidth = 1; ctx.setLineDash([3, 2]);
        ctx.strokeRect(rx1, PAD.top, rx2 - rx1, pH); ctx.setLineDash([]);

        // Data points
        DATA.forEach(d => {
            const isNeighbor = neighbors.some(n => n === d);
            const cx = toX(d.x), cy = toY(d.y);
            ctx.beginPath(); ctx.arc(cx, cy, isNeighbor ? 7 : 4, 0, Math.PI * 2);
            ctx.fillStyle = isNeighbor ? color : "#60a5fa";
            ctx.globalAlpha = isNeighbor ? 1 : 0.5;
            if (isNeighbor) { ctx.shadowColor = color; ctx.shadowBlur = 12; }
            ctx.fill(); ctx.shadowBlur = 0; ctx.globalAlpha = 1;
            if (isNeighbor) {
                ctx.strokeStyle = "#fff"; ctx.lineWidth = 1.5; ctx.stroke();
                ctx.fillStyle = "#000"; ctx.font = "bold 8px monospace"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
                ctx.fillText(d.y.toFixed(1), cx, cy); ctx.textBaseline = "alphabetic";
            }
        });

        // Query point
        const qx = toX(queryX), qy = toY(pred);
        ctx.beginPath(); ctx.arc(qx, qy, 9, 0, Math.PI * 2);
        ctx.fillStyle = "#fff"; ctx.shadowColor = "#fff"; ctx.shadowBlur = 16; ctx.fill(); ctx.shadowBlur = 0;
        ctx.strokeStyle = color; ctx.lineWidth = 2.5; ctx.stroke();
        ctx.fillStyle = color; ctx.font = "bold 8px monospace"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("?", qx, qy); ctx.textBaseline = "alphabetic";

        // Prediction label
        ctx.fillStyle = "#fff"; ctx.font = "bold 11px monospace"; ctx.textAlign = "left";
        ctx.fillText(`┼╖ = ${pred.toFixed(2)}`, qx + 12, qy + 4);

        // Axes
        ctx.strokeStyle = "#252535"; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(PAD.left, PAD.top); ctx.lineTo(PAD.left, PAD.top + pH);
        ctx.lineTo(PAD.left + pW, PAD.top + pH); ctx.stroke();
        ctx.fillStyle = THEME.dim; ctx.font = "10px monospace"; ctx.textAlign = "center";
        ctx.fillText("X ΓåÆ", PAD.left + pW / 2, H - 6);

        ctx.fillStyle = color; ctx.font = "bold 10px monospace"; ctx.textAlign = "right";
        const label = k === 1 ? "overfit (wiggly)" : k >= 15 ? "underfit (over-smooth)" : "good fit";
        ctx.fillText(`k = ${k}  (${label})`, PAD.left + pW - 4, PAD.top + 14);
    }

    const handleMouseMove = useCallback((e: React.MouseEvent) => {
        const canvas = canvasRef.current; if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const cx = e.clientX - rect.left;
        const scaleX = W / rect.width;
        const scaledCX = cx * scaleX;
        if (scaledCX >= PAD.left && scaledCX <= PAD.left + pW) {
            setQueryX(+Math.max(X_MIN + 0.1, Math.min(X_MAX - 0.1, fromCanvasX(scaledCX))).toFixed(3));
        }
    }, []);

    return (
        <div style={{ fontFamily: "'SF Mono','Fira Code',monospace", background: THEME.bg, padding: "24px 20px", color: THEME.text, borderRadius: "8px", border: `1px solid ${THEME.border}`, maxWidth: 800, margin: "0 auto" }}>
            <div style={{ textAlign: "center", marginBottom: "16px" }}>
                <div style={{ fontSize: "10px", letterSpacing: "4px", color: THEME.dim, marginBottom: "6px" }}>SUBJECT IV ┬╖ REGRESSION ┬╖ ┬º54</div>
                <h1 style={{ fontSize: "24px", fontWeight: 700, margin: "0 0 4px" }}>KNN Regression</h1>
                <p style={{ fontSize: "12px", color: THEME.dim, margin: 0, fontStyle: "italic" }}>
                    "KNN is Locality ΓÇö your value is just the average of the K people standing closest to you."
                </p>
            </div>

            <div style={{ border: `1px solid ${color}44`, borderRadius: "8px", overflow: "hidden", cursor: "crosshair", transition: "border-color 0.3s", background: THEME.surface, display: "flex", justifyContent: "center" }}
                onMouseMove={handleMouseMove}>
                <canvas ref={canvasRef} width={W} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
            </div>

            <div style={{ marginTop: "8px", fontSize: "11px", color: THEME.dim, textAlign: "center" }}>ΓåÉ MOVE MOUSE OVER CHART to reposition query point ΓåÆ</div>

            <div style={{ width: "100%", maxWidth: 480, marginTop: "12px", margin: "12px auto 0" }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "11px", color: THEME.dim, marginBottom: "6px" }}>
                    <span>k ΓÇö number of neighbors</span>
                    <span style={{ color }}>k = {k}</span>
                </div>
                <input type="range" min={1} max={20} step={1} value={k}
                    onChange={e => setK(+e.target.value)}
                    style={{ width: "100%", accentColor: color, cursor: "pointer" }} />
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: "10px", color: THEME.dim, marginTop: "4px" }}>
                    <span>k=1 (jagged, overfit)</span><span>k=20 (smooth, underfit)</span>
                </div>
            </div>

            <div style={{ marginTop: "14px", padding: "10px 18px", borderLeft: `3px solid ${color}`, background: color + "0f", maxWidth: 500, fontSize: "11px", color: THEME.dim, lineHeight: 1.8, borderRadius: "0 4px 4px 0", margin: "14px auto 0" }}>
                <span style={{ color }}>// BIAS-VARIANCE:</span> k=1 memorises every point (zero bias, high variance). Large k averages too broadly (high bias, low variance). The shaded box shows which k neighbours contribute to the white query point's prediction.
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { motion } from "framer-motion";

// ΓöÇΓöÇΓöÇ Constants & Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const W = 660, H = 400;
const HISTORY_STEP = 10;
const MAX_N = 2500;

type DistributionKey = 'fair_die' | 'coin' | 'exponential' | 'skewed';

interface Distribution {
    name: string;
    mu: number;
    sample: () => number;
}

const DISTRIBUTIONS: Record<DistributionKey, Distribution> = {
    fair_die: { name: 'Fair Die', mu: 3.5, sample: () => Math.floor(Math.random() * 6) + 1 },
    coin: { name: 'Coin Flip', mu: 0.5, sample: () => Math.random() < 0.5 ? 0 : 1 },
    exponential: { name: 'Exponential', mu: 2, sample: () => -2 * Math.log(1 - Math.random()) },
    skewed: {
        name: 'Skewed', mu: 1, sample: () => {
            const u1 = Math.random(), u2 = Math.random();
            return -Math.log(u1) - Math.log(u2);
        }
    }
};

interface Trial {
    id: string;
    color: string;
    sum: number;
    count: number;
    history: [number, number][]; // [n, runningMean]
}

const COLORS = [
    "hsl(var(--primary))",
    "hsl(var(--secondary))",
    "hsl(var(--accent))",
    "hsl(var(--emerald-500))",
    "hsl(var(--amber-500))",
    "hsl(var(--rose-500))"
];

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function LawOfLargeNumbersPrimitive() {
    const [distKey, setDistKey] = useState<DistributionKey>('fair_die');
    const [trials, setTrials] = useState<Trial[]>([]);
    const [running, setRunning] = useState(false);
    const [speed, setSpeed] = useState(100);
    const [n, setN] = useState(0);

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const trialsRef = useRef<Trial[]>([]);
    const requestRef = useRef<number | undefined>(undefined);

    const currentDist = DISTRIBUTIONS[distKey];

    // Initialize
    const reset = useCallback((initialCount = 3) => {
        setRunning(false);
        if (requestRef.current) cancelAnimationFrame(requestRef.current);

        const newTrials: Trial[] = Array.from({ length: initialCount }).map((_, i) => ({
            id: Math.random().toString(36).substr(2, 9),
            color: COLORS[i % COLORS.length],
            sum: 0,
            count: 0,
            history: [[0, 0]]
        }));

        trialsRef.current = newTrials;
        setTrials(newTrials);
        setN(0);
    }, []);

    useEffect(() => { reset(3); }, [reset, distKey]);

    const addTrial = () => {
        if (trialsRef.current.length >= COLORS.length) return;
        const newTrial: Trial = {
            id: Math.random().toString(36).substr(2, 9),
            color: COLORS[trialsRef.current.length],
            sum: 0,
            count: 0,
            history: [[0, 0]]
        };
        trialsRef.current = [...trialsRef.current, newTrial];
        setTrials(trialsRef.current);
    };

    const update = useCallback(() => {
        const activeDist = DISTRIBUTIONS[distKey];
        let maxNReached = true;

        for (const t of trialsRef.current) {
            if (t.count < MAX_N) {
                maxNReached = false;
                for (let i = 0; i < speed; i++) {
                    if (t.count >= MAX_N) break;
                    t.sum += activeDist.sample();
                    t.count++;
                    if (t.count % HISTORY_STEP === 0) {
                        t.history.push([t.count, t.sum / t.count]);
                    }
                }
            }
        }

        const currentMaxN = Math.max(...trialsRef.current.map(t => t.count));
        setN(currentMaxN);
        setTrials([...trialsRef.current]);

        if (maxNReached) {
            setRunning(false);
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        }
    }, [distKey, speed]);

    const draw = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        ctx.clearRect(0, 0, W, H);

        // Margins
        const M = { top: 30, right: 60, bottom: 50, left: 60 };
        const CW = W - M.left - M.right;
        const CH = H - M.top - M.bottom;

        const mu = DISTRIBUTIONS[distKey].mu;

        // Scale Logic
        const allMeans = trialsRef.current.flatMap(t => t.history.map(h => h[1])).filter(v => v > 0);
        let yMin = allMeans.length ? Math.min(...allMeans, mu) : 0;
        let yMax = allMeans.length ? Math.max(...allMeans, mu) : mu * 2;
        const yPad = (yMax - yMin) * 0.2 || 0.5;
        yMin -= yPad; yMax += yPad;

        const toX = (val: number) => M.left + (val / MAX_N) * CW;
        const toY = (val: number) => M.top + CH - ((val - yMin) / (yMax - yMin) * CH);

        // Grid Pins & Lines
        ctx.strokeStyle = "rgba(255, 255, 255, 0.05)";
        ctx.lineWidth = 1;

        // Y-Axis Ticks
        ctx.font = "9px var(--font-jetbrains)";
        ctx.fillStyle = "rgba(255, 255, 255, 0.4)";
        ctx.textAlign = "right";
        for (let i = 0; i <= 5; i++) {
            const val = yMin + (yMax - yMin) * i / 5;
            const py = toY(val);
            ctx.beginPath(); ctx.moveTo(M.left, py); ctx.lineTo(M.left + CW, py); ctx.stroke();
            ctx.fillText(val.toFixed(1), M.left - 10, py + 3);
        }

        // X-Axis Ticks
        ctx.textAlign = "center";
        [0, 500, 1000, 1500, 2000, 2500].forEach(tx => {
            const px = toX(tx);
            ctx.beginPath(); ctx.moveTo(px, M.top); ctx.lineTo(px, M.top + CH); ctx.stroke();
            ctx.fillText(tx.toString(), px, M.top + CH + 20);
        });

        // TRUE VALUE LINE
        const muY = toY(mu);
        ctx.setLineDash([5, 5]);
        ctx.strokeStyle = "hsla(var(--emerald-500), 0.6)";
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(M.left, muY); ctx.lineTo(M.left + CW, muY); ctx.stroke();
        ctx.setLineDash([]);

        // Label for mu
        ctx.fillStyle = "hsl(var(--emerald-500))";
        ctx.font = "bold 10px var(--font-jetbrains)";
        ctx.textAlign = "left";
        ctx.fillText(`╬╝ = ${mu}`, M.left + CW + 10, muY + 3);

        // Draw Trials
        trialsRef.current.forEach(t => {
            if (t.history.length < 2) return;

            ctx.beginPath();
            ctx.strokeStyle = t.color;
            ctx.lineWidth = 2;
            ctx.lineJoin = "round";

            t.history.forEach(([tn, tm], idx) => {
                if (tn === 0) return;
                const px = toX(tn), py = toY(tm);
                idx === 1 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
            });
            ctx.stroke();

            // End Dot
            const last = t.history[t.history.length - 1];
            if (last[0] > 0) {
                ctx.beginPath();
                ctx.arc(toX(last[0]), toY(last[1]), 4, 0, Math.PI * 2);
                ctx.fillStyle = t.color;
                ctx.fill();
                ctx.strokeStyle = "black";
                ctx.lineWidth = 1;
                ctx.stroke();
            }
        });

        // Border
        ctx.strokeStyle = "rgba(255, 255, 255, 0.1)";
        ctx.lineWidth = 2;
        ctx.strokeRect(M.left, M.top, CW, CH);

    }, [distKey]);

    const animate = useCallback(() => {
        if (running) update();
        draw();
        requestRef.current = requestAnimationFrame(animate);
    }, [running, update, draw]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(animate);
        return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
    }, [animate]);

    // Insights
    const convergence = useMemo(() => {
        if (n === 0) return 0;
        const mu = currentDist.mu;
        const distances = trialsRef.current.map(t => Math.abs((t.sum / t.count) - mu) / mu);
        const avgDist = distances.reduce((a, b) => a + b, 0) / distances.length;
        return Math.max(0, Math.min(100, (1 - avgDist * 4) * 100));
    }, [n, currentDist, trials]);

    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div className="space-y-1">
                    <h3 className="text-sm font-bold text-muted uppercase tracking-wider flex items-center gap-2">
                        <span className="material-symbols-outlined text-base">trending_flat</span>
                        The Law of Large Numbers
                    </h3>
                    <p className="text-xs text-muted/60 italic lowercase">Watching randomness converge into truth (N={n})</p>
                </div>
                <div className="flex items-center gap-2">
                    {(Object.keys(DISTRIBUTIONS) as DistributionKey[]).map(k => (
                        <button
                            key={k}
                            onClick={() => setDistKey(k)}
                            className={`px-3 py-1.5 rounded-full border text-[10px] font-bold uppercase transition-all ${distKey === k ? "bg-emerald-500/20 border-emerald-500 text-emerald-500" : "bg-surface border-border text-muted hover:border-muted"
                                }`}
                        >
                            {DISTRIBUTIONS[k].name}
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                <div className="lg:col-span-8 space-y-4">
                    <div className="bg-black/40 border border-border/50 rounded-xl overflow-hidden shadow-2xl relative">
                        <canvas ref={canvasRef} width={W} height={H} className="w-full h-auto" />
                        {!running && n === 0 && (
                            <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px]">
                                <button onClick={() => setRunning(true)} className="px-6 py-3 bg-emerald-500 text-black font-black rounded-lg text-xs tracking-widest uppercase hover:scale-105 transition-all shadow-[0_0_20px_rgba(16,185,129,0.4)]">
                                    Begin Simulation
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="col-span-1 bg-surface/80 border border-border rounded-lg p-4 space-y-3">
                            <div className="text-[10px] font-bold text-muted uppercase tracking-widest">Simulation Speed</div>
                            <div className="space-y-2">
                                <div className="flex justify-between text-[10px] text-muted/60">
                                    <span>Slower</span>
                                    <span className="text-emerald-500 font-mono font-bold">{speed}x</span>
                                </div>
                                <input
                                    type="range" min="10" max="800" step="10"
                                    value={speed} onChange={e => setSpeed(+e.target.value)}
                                    className="w-full h-1 bg-border rounded-full appearance-none accent-emerald-500"
                                />
                            </div>
                        </div>
                        <div className="col-span-2 flex gap-2">
                            <button
                                onClick={() => setRunning(!running)}
                                className={`flex-1 rounded-lg border font-bold text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${running ? "bg-rose-500/20 border-rose-500 text-rose-500" : "bg-emerald-500/20 border-emerald-500 text-emerald-500"
                                    }`}
                            >
                                <span className="material-symbols-outlined text-sm">{running ? "pause" : "play_arrow"}</span>
                                {running ? "Pause" : "Run Sampling"}
                            </button>
                            <button onClick={addTrial} className="px-4 bg-surface border border-border rounded-lg text-muted hover:text-white transition-all">
                                <span className="material-symbols-outlined text-sm">add</span>
                            </button>
                            <button onClick={() => reset()} className="px-4 bg-surface border border-border rounded-lg text-muted hover:text-rose-400 transition-all">
                                <span className="material-symbols-outlined text-sm">refresh</span>
                            </button>
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-4 space-y-4">
                    <div className="bg-surface border border-border rounded-xl p-5 space-y-4">
                        <div className="text-[10px] font-bold text-muted uppercase tracking-widest border-b border-border pb-2">Running Trial Means</div>
                        <div className="space-y-3 max-h-[220px] overflow-y-auto pr-2 custom-scrollbar">
                            {trials.map((t, idx) => {
                                const currentMean = t.count > 0 ? (t.sum / t.count) : 0;
                                const diff = Math.abs(currentMean - currentDist.mu);
                                return (
                                    <div key={t.id} className="flex items-center justify-between text-[11px]">
                                        <div className="flex items-center gap-2">
                                            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: t.color }} />
                                            <span className="text-muted font-medium">Trial {idx + 1}</span>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <span className="font-mono font-bold">{currentMean.toFixed(3)}</span>
                                            <span className={`text-[9px] font-mono ${diff < 0.01 ? "text-emerald-500" : "text-muted/40"}`}>
                                                ╬ö{diff.toFixed(3)}
                                            </span>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>

                    <div className="bg-surface/80 border border-border rounded-xl p-5 space-y-4 text-center">
                        <div className="text-[10px] font-bold text-muted uppercase tracking-widest">Convergence Meter</div>
                        <div className="relative inline-flex items-center justify-center">
                            <svg className="w-24 h-24 transform -rotate-90">
                                <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-border/40" />
                                <motion.circle
                                    cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent"
                                    className="text-emerald-500"
                                    style={{ strokeDasharray: 251.2, strokeDashoffset: 251.2 - (251.2 * convergence / 100) }}
                                />
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-lg font-black font-mono leading-none">{convergence.toFixed(0)}%</span>
                                <span className="text-[8px] text-muted uppercase font-bold tracking-tighter">Unified</span>
                            </div>
                        </div>
                        <p className="text-[10px] text-muted leading-relaxed px-2">
                            At <span className="text-foreground">N={n.toLocaleString()}</span>, the mathematical truth is successfully drowning out the short-term noise.
                        </p>
                    </div>

                    <div className="p-4 bg-emerald-500/5 border border-emerald-500/10 rounded-xl flex gap-3">
                        <span className="material-symbols-outlined text-emerald-500">psychology</span>
                        <p className="text-[10px] text-muted leading-relaxed">
                            <span className="text-emerald-500 font-bold uppercase italic">The Axiom:</span> In the short term, randomness is chaos. In the long term, it is perfectly predictable. This is the bedrock of insurance, gambling, and probability theory.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";

// ΓöÇΓöÇΓöÇ Constants & Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const CW = 720, CH = 460;
const SCALE = 60;

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function LinearIndependencePrimitive() {
    const [v1, _setV1] = useState({ x: 2, y: 1 });
    const [v2Angle, setV2Angle] = useState(45);
    const [v2Mag, setV2Mag] = useState(2);

    const canvasRef = useRef<HTMLCanvasElement>(null);

    const OX = CW / 2, OY = CH / 2;

    const v2 = {
        x: v2Mag * Math.cos((v2Angle * Math.PI) / 180),
        y: v2Mag * Math.sin((v2Angle * Math.PI) / 180),
    };

    const determinant = v1.x * v2.y - v1.y * v2.x;
    const isIndependent = Math.abs(determinant) > 0.05;

    // ΓöÇΓöÇΓöÇ Drawing Logic ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const drawGrid = (ctx: CanvasRenderingContext2D) => {
        ctx.save();
        ctx.strokeStyle = "rgba(255, 255, 255, 0.05)";
        ctx.lineWidth = 1;

        for (let x = -10; x <= 10; x++) {
            ctx.beginPath();
            ctx.moveTo(OX + x * SCALE, 0);
            ctx.lineTo(OX + x * SCALE, CH);
            ctx.stroke();
        }

        for (let y = -10; y <= 10; y++) {
            ctx.beginPath();
            ctx.moveTo(0, OY - y * SCALE);
            ctx.lineTo(CW, OY - y * SCALE);
            ctx.stroke();
        }

        ctx.strokeStyle = "rgba(255, 255, 255, 0.15)";
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(0, OY); ctx.lineTo(CW, OY); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(OX, 0); ctx.lineTo(OX, CH); ctx.stroke();
        ctx.restore();
    };

    const drawVector = (ctx: CanvasRenderingContext2D, v: { x: number, y: number }, color: string, label: string) => {
        const endX = OX + v.x * SCALE;
        const endY = OY - v.y * SCALE;

        ctx.save();
        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.lineWidth = 4;

        ctx.beginPath();
        ctx.moveTo(OX, OY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        const angle = Math.atan2(OY - endY, endX - OX);
        const headLength = 12;

        ctx.beginPath();
        ctx.moveTo(endX, endY);
        ctx.lineTo(
            endX - headLength * Math.cos(angle - 0.4),
            endY + headLength * Math.sin(angle - 0.4)
        );
        ctx.lineTo(
            endX - headLength * Math.cos(angle + 0.4),
            endY + headLength * Math.sin(angle + 0.4)
        );
        ctx.closePath();
        ctx.fill();

        ctx.font = "bold 14px var(--font-jetbrains)";
        ctx.fillText(label, endX + 8, endY - 8);
        ctx.restore();
    };

    const drawSpan = (ctx: CanvasRenderingContext2D) => {
        ctx.save();
        if (isIndependent) {
            ctx.globalAlpha = 0.2;
            ctx.fillStyle = "hsl(var(--primary))";

            // Draw a large parallelogram representing the span coverage
            const range = 5;
            const p1 = { x: v1.x * range, y: v1.y * range };
            const p2 = { x: v2.x * range, y: v2.y * range };

            ctx.beginPath();
            ctx.moveTo(OX - p1.x * SCALE - p2.x * SCALE, OY + p1.y * SCALE + p2.y * SCALE);
            ctx.lineTo(OX + p1.x * SCALE - p2.x * SCALE, OY - p1.y * SCALE + p2.y * SCALE);
            ctx.lineTo(OX + p1.x * SCALE + p2.x * SCALE, OY - p1.y * SCALE - p2.y * SCALE);
            ctx.lineTo(OX - p1.x * SCALE + p2.x * SCALE, OY + p1.y * SCALE - p2.y * SCALE);
            ctx.closePath();
            ctx.fill();
        } else {
            ctx.strokeStyle = "hsla(var(--rose-400), 0.4)";
            ctx.lineWidth = 5;
            const angle = Math.atan2(v1.y, v1.x);
            const range = 10;
            ctx.beginPath();
            ctx.moveTo(OX - range * SCALE * Math.cos(angle), OY + range * SCALE * Math.sin(angle));
            ctx.lineTo(OX + range * SCALE * Math.cos(angle), OY - range * SCALE * Math.sin(angle));
            ctx.stroke();
        }
        ctx.restore();
    };

    const draw = useCallback(() => {
        const ctx = canvasRef.current?.getContext("2d");
        if (!ctx) return;

        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = "hsl(var(--surface))";
        ctx.fillRect(0, 0, CW, CH);

        drawGrid(ctx);
        drawSpan(ctx);
