            ctx.beginPath(); ctx.moveTo(OX + p0.x * SCALE, OY - p0.y * SCALE); ctx.lineTo(OX + p1.x * SCALE, OY - p1.y * SCALE); ctx.stroke();
        }
        for (let y = -range; y <= range; y++) {
            const p0 = applyM(mat, { x: -range, y }), p1 = applyM(mat, { x: range, y });
            ctx.beginPath(); ctx.moveTo(OX + p0.x * SCALE, OY - p0.y * SCALE); ctx.lineTo(OX + p1.x * SCALE, OY - p1.y * SCALE); ctx.stroke();
        }
        ctx.restore();
