"use client";

import { useState, useEffect, useRef, useCallback } from "react";

const W = 540, H = 280;
const PAD = { top: 28, right: 24, bottom: 44, left: 54 };
const pW = W - PAD.left - PAD.right;
const pH = H - PAD.top - PAD.bottom;

function randNorm(m = 0, s = 1) {
    let u = 0; while (!u) u = Math.random();
    return m + s * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random());
}

// Fixed data points on a line
const LINE_M = 1.1, LINE_B = 2;
const FIXED_PTS = Array.from({ length: 12 }, (_, i) => {
    const x = 1 + i * 0.65;
    return { x: +x.toFixed(2), y: +(LINE_M * x + LINE_B + randNorm(0, 0.5)).toFixed(2), fixed: true };
});

const X_MIN = 0, X_MAX = 10, Y_MIN = 0, Y_MAX = 14;
function toX(x: number) { return PAD.left + ((x - X_MIN) / (X_MAX - X_MIN)) * pW; }
function toY(y: number) { return PAD.top + pH - ((y - Y_MIN) / (Y_MAX - Y_MIN)) * pH; }
function fromCanvas(cx: number, cy: number) {
    return {
        x: X_MIN + ((cx - PAD.left) / pW) * (X_MAX - X_MIN),
        y: Y_MIN + ((PAD.top + pH - cy) / pH) * (Y_MAX - Y_MIN)
    };
}

const THEME = { bg: "#08090d", surface: "#0d0e18", border: "#1a1b2c", text: "#e2e8f0", dim: "#374151", grid: "#111827" };

export default function RegressionMetricsPrimitive() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [outlier, setOutlier] = useState({ x: 6, y: 11.5, fixed: false });
    const [dragging, setDragging] = useState(false);
    const [metric, setMetric] = useState("both");

    const allPts = [...FIXED_PTS, outlier];
    const errors = allPts.map(p => p.y - (LINE_M * p.x + LINE_B));
    const absErrors = errors.map(Math.abs);
    const mae = absErrors.reduce((s, e) => s + e, 0) / allPts.length;
    const rmse = Math.sqrt(errors.reduce((s, e) => s + e * e, 0) / allPts.length);
    const outlierError = Math.abs(outlier.y - (LINE_M * outlier.x + LINE_B));

    useEffect(() => { draw(); }, [outlier, metric]);

    function draw() {
        const canvas = canvasRef.current; if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;
        ctx.clearRect(0, 0, W, H); ctx.fillStyle = THEME.surface; ctx.fillRect(0, 0, W, H);

        // Grid
        ctx.strokeStyle = THEME.grid; ctx.lineWidth = 1;
        for (let i = 0; i <= 4; i++) {
            const y = PAD.top + (i / 4) * pH;
            ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + pW, y); ctx.stroke();
        }

        // Regression line
        ctx.beginPath();
        ctx.moveTo(toX(X_MIN), toY(LINE_M * X_MIN + LINE_B));
        ctx.lineTo(toX(X_MAX), toY(LINE_M * X_MAX + LINE_B));
        ctx.strokeStyle = "#60a5fa"; ctx.lineWidth = 2; ctx.stroke();

        // Error visualizations
        allPts.forEach(pt => {
            const pred = LINE_M * pt.x + LINE_B;
            const err = Math.abs(pt.y - pred);
            const cx = toX(pt.x);
            const isOutlier = !pt.fixed;

            if (metric !== "rmse") {
                // MAE: absolute stick
                ctx.beginPath(); ctx.moveTo(cx, toY(pt.y)); ctx.lineTo(cx, toY(pred));
                ctx.strokeStyle = isOutlier ? "#fbbf24aa" : "#34d39955";
                ctx.lineWidth = isOutlier ? 2.5 : 1.5; ctx.stroke();
            }

            if (metric !== "mae") {
                // RMSE: square drawn to the right
                const sqSize = (err / (Y_MAX - Y_MIN)) * pH;
                const sqX = cx + 4;
                const sqY = Math.min(toY(pt.y), toY(pred));
                ctx.fillStyle = isOutlier ? "#f8717133" : "#f4728b22";
                ctx.fillRect(sqX, sqY, sqSize, sqSize);
                ctx.strokeStyle = isOutlier ? "#f87171aa" : "#f4728b55";
                ctx.lineWidth = isOutlier ? 1.5 : 0.8; ctx.strokeRect(sqX, sqY, sqSize, sqSize);
            }
        });

        // Fixed data pts
        FIXED_PTS.forEach(pt => {
            ctx.beginPath(); ctx.arc(toX(pt.x), toY(pt.y), 4, 0, Math.PI * 2);
            ctx.fillStyle = "#60a5fa"; ctx.globalAlpha = 0.8; ctx.fill(); ctx.globalAlpha = 1;
        });

        // Draggable outlier
        const ox = toX(outlier.x), oy = toY(outlier.y);
        ctx.beginPath(); ctx.arc(ox, oy, 10, 0, Math.PI * 2);
        ctx.fillStyle = "#fbbf24"; ctx.shadowColor = "#fbbf24"; ctx.shadowBlur = 18; ctx.fill(); ctx.shadowBlur = 0;
        ctx.strokeStyle = "#fff"; ctx.lineWidth = 2; ctx.stroke();
        ctx.fillStyle = "#000"; ctx.font = "bold 9px monospace"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("Γ£ª", ox, oy); ctx.textBaseline = "alphabetic";

        // Axes
        ctx.strokeStyle = "#252535"; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(PAD.left, PAD.top); ctx.lineTo(PAD.left, PAD.top + pH);
        ctx.lineTo(PAD.left + pW, PAD.top + pH); ctx.stroke();
        ctx.fillStyle = THEME.dim; ctx.font = "10px monospace"; ctx.textAlign = "center";
        ctx.fillText("X ΓåÆ", PAD.left + pW / 2, H - 6);

        // Metric readout
        ctx.textAlign = "right"; ctx.font = "bold 10px monospace";
        ctx.fillStyle = "#34d399"; ctx.fillText(`MAE  = ${mae.toFixed(3)}`, PAD.left + pW - 4, PAD.top + 14);
        ctx.fillStyle = "#f87171"; ctx.fillText(`RMSE = ${rmse.toFixed(3)}`, PAD.left + pW - 4, PAD.top + 28);
        ctx.fillStyle = "#fbbf24"; ctx.fillText(`outlier err = ${outlierError.toFixed(2)}`, PAD.left + pW - 4, PAD.top + 42);
    }

    const handleDown = useCallback((e: React.MouseEvent) => {
        const canvas = canvasRef.current; if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const scaleX = W / rect.width;
        const scaleY = H / rect.height;
        const cx = (e.clientX - rect.left) * scaleX;
        const cy = (e.clientY - rect.top) * scaleY;
        const d = Math.hypot(cx - toX(outlier.x), cy - toY(outlier.y));
        if (d < 20) setDragging(true);
    }, [outlier]);

    const handleMove = useCallback((e: React.MouseEvent) => {
        if (!dragging) return;
        const canvas = canvasRef.current; if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const scaleX = W / rect.width;
        const scaleY = H / rect.height;
        const { x, y } = fromCanvas((e.clientX - rect.left) * scaleX, (e.clientY - rect.top) * scaleY);
        setOutlier({ x: Math.max(0.1, Math.min(9.9, x)), y: Math.max(0.2, Math.min(13.9, y)), fixed: false });
    }, [dragging]);

    const handleUp = useCallback(() => setDragging(false), []);

    return (
        <div style={{ fontFamily: "'SF Mono','Fira Code',monospace", background: THEME.bg, padding: "24px 20px", color: THEME.text, borderRadius: "8px", border: `1px solid ${THEME.border}`, maxWidth: 800, margin: "0 auto" }}>
            <div style={{ textAlign: "center", marginBottom: "16px" }}>
                <div style={{ fontSize: "10px", letterSpacing: "4px", color: THEME.dim, marginBottom: "6px" }}>SUBJECT IV ┬╖ REGRESSION ┬╖ ┬º56</div>
                <h1 style={{ fontSize: "24px", fontWeight: 700, margin: "0 0 4px" }}>Regression Metrics</h1>
                <p style={{ fontSize: "12px", color: THEME.dim, margin: 0, fontStyle: "italic" }}>
                    "MAE tells you the Average Mistake; RMSE is a strict parent who punishes large mistakes harder."
                </p>
            </div>

            <div style={{ display: "flex", gap: "8px", marginBottom: "12px", justifyContent: "center" }}>
                {[
                    { key: "mae", label: "MAE only", color: "#34d399" },
                    { key: "both", label: "Both", color: "#94a3b8" },
                    { key: "rmse", label: "RMSE only", color: "#f87171" },
                ].map(({ key, label, color }) => (
                    <button key={key} onClick={() => setMetric(key)}
                        style={{ padding: "6px 14px", border: `1.5px solid ${metric === key ? color : THEME.border}`, borderRadius: "4px", background: metric === key ? color + "22" : "transparent", color: metric === key ? color : THEME.dim, fontSize: "11px", fontFamily: "inherit", cursor: "pointer" }}>
                        {label}
                    </button>
                ))}
            </div>

            <div style={{ border: `1px solid ${THEME.border}`, borderRadius: "8px", overflow: "hidden", cursor: dragging ? "grabbing" : "grab", background: THEME.surface, display: "flex", justifyContent: "center" }}
                onMouseDown={handleDown} onMouseMove={handleMove} onMouseUp={handleUp} onMouseLeave={handleUp}>
                <canvas ref={canvasRef} width={W} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
            </div>

            <div style={{ marginTop: "8px", fontSize: "11px", color: "#fbbf24", textAlign: "center" }}>ΓåÉ DRAG THE GOLD STAR Γ£ª far from the line to see the metrics diverge ΓåÆ</div>

            <div style={{ marginTop: "14px", display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: "10px", maxWidth: 600, width: "100%", margin: "14px auto 0" }}>
                {[
                    { label: "MAE (Mean Absolute Error)", color: "#34d399", formula: "╬ú|yß╡ó - ┼╖ß╡ó| / n", pts: ["Equal weight to all errors", "Robust to outliers", "Same units as target", "Good for: skewed distributions"] },
                    { label: "RMSE (Root Mean Sq. Error)", color: "#f87171", formula: "ΓêÜ( ╬ú(yß╡ó-┼╖ß╡ó)┬▓ / n )", pts: ["Large errors penalised heavily", "Sensitive to outliers", "Differentiable everywhere", "Good for: Gaussian errors"] },
                ].map(({ label, color, formula, pts }) => (
                    <div key={label} style={{ border: `1px solid ${color}33`, borderRadius: "6px", padding: "10px 12px", background: color + "08" }}>
                        <div style={{ fontSize: "10px", color, fontWeight: 700, marginBottom: "4px" }}>{label}</div>
                        <div style={{ fontSize: "10px", color: color + "aa", marginBottom: "6px", fontFamily: "monospace" }}>{formula}</div>
                        {pts.map(p => <div key={p} style={{ fontSize: "9px", color: THEME.dim, marginBottom: "3px" }}>┬╖ {p}</div>)}
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";
import React, { useState, useEffect, useRef } from "react";

const W = 500, H = 260, PAD = { top: 28, right: 24, bottom: 44, left: 54 };
const pW = W - PAD.left - PAD.right, pH = H - PAD.top - PAD.bottom;
let _s = 33;
function rng() { _s = (_s * 9301 + 49297) % 233280; return _s / 233280; }
function rn(m = 0, s = 1) { let u = 0; while (!u) u = rng(); return m + s * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rng()); }
_s = 33;
const N = 70;
const xVals = Array.from({ length: N }, (_, i) => i * 1.2 + rn(0, 0.5));
const goodRes = xVals.map(() => rn(0, 2.5));
const poorRes = xVals.map((x) => rn(0, 0.5 + x * 0.18) + Math.sin(x * 0.3) * 3);
const xMax = Math.max(...xVals) + 1;
const MODES = [
    { key: "good", label: "Γ£ô Clean Data", color: "#34d399", residuals: goodRes, desc: "Random scatter ΓÇö no pattern. Model has captured all signal." },
    { key: "poor", label: "Γ£ù Problematic", color: "#f87171", residuals: poorRes, desc: "Funnel + curve pattern ΓÇö heteroscedasticity and missed non-linearity." },
] as const;
type MK = "good" | "poor";

export default function ResidualAnalysisPrimitive() {
    const cvs = useRef<HTMLCanvasElement>(null);
    const [mode, setMode] = useState<MK>("good");
    const m = MODES.find(x => x.key === mode)!;
    const resids = m.residuals;
    const sd = Math.sqrt(resids.reduce((s, r) => s + r * r, 0) / resids.length);

    function toX(x: number) { return PAD.left + (x / xMax) * pW; }
    function toY(r: number) { return PAD.top + pH / 2 - (r / Math.max(Math.abs(Math.min(...resids)), Math.max(...resids))) * (pH / 2 - 8); }

    useEffect(() => {
        const canvas = cvs.current; if (!canvas) return;
        const ctx = canvas.getContext("2d")!;
        ctx.clearRect(0, 0, W, H); ctx.fillStyle = "#0d0e18"; ctx.fillRect(0, 0, W, H);
        ctx.strokeStyle = "#111827"; ctx.lineWidth = 1;
        [-2, -1, 0, 1, 2].forEach(i => { const y = PAD.top + pH / 2 - i / 2.5 * (pH / 2 - 8); ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + pW, y); ctx.stroke(); });
        // Zero line
        ctx.beginPath(); ctx.moveTo(PAD.left, toY(0)); ctx.lineTo(PAD.left + pW, toY(0));
        ctx.strokeStyle = "#334155"; ctx.lineWidth = 1.5; ctx.stroke();
        ctx.fillStyle = "#374151"; ctx.font = "9px monospace"; ctx.textAlign = "left"; ctx.fillText("0", PAD.left - 18, toY(0) + 4);
        // ┬▒2╧â bands
        [-1, 1].forEach(sign => {
            const y = toY(sign * 2 * sd);
            ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + pW, y);
            ctx.strokeStyle = m.color + "33"; ctx.lineWidth = 1; ctx.setLineDash([3, 3]); ctx.stroke(); ctx.setLineDash([]);
            ctx.fillStyle = m.color + "66"; ctx.font = "9px monospace"; ctx.textAlign = "right"; ctx.fillText(`${sign > 0 ? "+" : ""}${(sign * 2 * sd).toFixed(1)}`, PAD.left - 4, y + 4);
        });
        // Stems + dots
        xVals.forEach((x, i) => {
            const r = resids[i], cx = toX(x), cy = toY(r), outlier = Math.abs(r) > 2 * sd;
            ctx.beginPath(); ctx.moveTo(cx, toY(0)); ctx.lineTo(cx, cy); ctx.strokeStyle = m.color + "22"; ctx.lineWidth = 0.8; ctx.stroke();
            ctx.beginPath(); ctx.arc(cx, cy, outlier ? 5 : 3.5, 0, Math.PI * 2);
            ctx.fillStyle = m.color; ctx.globalAlpha = 0.8; if (outlier) { ctx.shadowColor = m.color; ctx.shadowBlur = 8; } ctx.fill(); ctx.shadowBlur = 0; ctx.globalAlpha = 1;
        });
        // Poor pattern overlay
        if (mode === "poor") {
            ctx.beginPath(); for (let i = 0; i <= 100; i++) { const x = i / 100 * xMax, tr = Math.sin(x * 0.3) * 3; i === 0 ? ctx.moveTo(toX(x), toY(tr)) : ctx.lineTo(toX(x), toY(tr)); }
            ctx.strokeStyle = "#f8717166"; ctx.lineWidth = 2; ctx.setLineDash([5, 3]); ctx.stroke(); ctx.setLineDash([]);
            ctx.fillStyle = "#f87171"; ctx.font = "10px monospace"; ctx.textAlign = "left"; ctx.fillText("Γåæ non-random pattern = missed signal", PAD.left + 4, PAD.top + 14);
        }
        // Axes
        ctx.strokeStyle = "#252535"; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(PAD.left, PAD.top); ctx.lineTo(PAD.left, PAD.top + pH); ctx.lineTo(PAD.left + pW, PAD.top + pH); ctx.stroke();
        ctx.fillStyle = "#374151"; ctx.font = "10px monospace"; ctx.textAlign = "center"; ctx.fillText("Fitted values ΓåÆ", PAD.left + pW / 2, H - 8);
        ctx.save(); ctx.translate(13, PAD.top + pH / 2); ctx.rotate(-Math.PI / 2); ctx.fillText("Residuals", 0, 0); ctx.restore();
        const rmse = Math.sqrt(resids.reduce((s, r) => s + r * r, 0) / resids.length).toFixed(2);
        ctx.fillStyle = m.color; ctx.font = "bold 10px monospace"; ctx.textAlign = "right"; ctx.fillText(`RMSE = ${rmse}`, PAD.left + pW - 4, PAD.top + 16);
    }, [mode]);

    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-5 select-none">
            <div className="flex flex-col md:flex-row justify-between gap-4">
                <div className="space-y-1">
                    <h3 className="text-sm font-bold text-muted uppercase tracking-wider flex items-center gap-2">
                        <span className="material-symbols-outlined text-base">analytics</span>Residual Analysis
                    </h3>
                    <p className="text-xs text-muted/60">Residuals are Errors. If they have a pattern, your model missed a pattern in the data.</p>
                </div>
                <div className="flex gap-2 shrink-0">
                    {MODES.map(mo => (
                        <button key={mo.key} onClick={() => setMode(mo.key)}
                            className="px-4 py-2 rounded-lg border text-[10px] font-black uppercase tracking-widest transition-all"
                            style={mode === mo.key ? { color: mo.color, background: mo.color + "18", borderColor: mo.color + "55" } : { color: "rgba(255,255,255,0.25)", borderColor: "rgba(255,255,255,0.08)" }}>
                            {mo.label}
                        </button>
                    ))}
                </div>
            </div>
            <div className="rounded-xl overflow-hidden" style={{ border: `1px solid ${m.color}33`, boxShadow: `0 0 28px ${m.color}18` }}>
                <canvas ref={cvs} width={W} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
            </div>
            <div className="text-center text-[11px] rounded-lg px-4 py-3" style={{ border: `1px solid ${m.color}22`, color: m.color }}>{m.desc}</div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {[
                    { label: "Good residual plot", color: "#34d399", pts: ["Random scatter around zero", "Constant variance (homoscedastic)", "No curved trends or clusters"] },
                    { label: "Bad residual plot", color: "#f87171", pts: ["Funnel ΓåÆ heteroscedasticity", "Curve ΓåÆ missing polynomial terms", "Clusters ΓåÆ missing categorical feature"] },
                ].map(({ label, color, pts }) => (
                    <div key={label} className="rounded-xl p-4" style={{ border: `1px solid ${color}25`, background: color + "08" }}>
                        <div className="text-[10px] font-black mb-2" style={{ color }}>{label}</div>
                        {pts.map(p => <div key={p} className="text-[9px] text-muted/50 mb-1">┬╖ {p}</div>)}
                    </div>
                ))}
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import { RollingAverageConfig } from "@/adapters/visual-types";

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const W = 560, H = 260;
const PAD = { top: 24, right: 20, bottom: 36, left: 40 };
const pW = W - PAD.left - PAD.right;
const pH = H - PAD.top - PAD.bottom;
const N = 80;

// ΓöÇΓöÇΓöÇ Generate data once ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
let _seed = 42;
function seededRng() { _seed = (_seed * 9301 + 49297) % 233280; return _seed / 233280; }

const DATA = (() => {
    let val = 50;
    return Array.from({ length: N }, (_, i) => {
        val += (seededRng() - 0.48) * 8 + Math.sin(i / 10) * 2;
        val = Math.max(20, Math.min(80, val));
        return +val.toFixed(2);
    });
})();

const YMIN = Math.min(...DATA) - 3;
const YMAX = Math.max(...DATA) + 3;

function toX(i: number) { return PAD.left + (i / (N - 1)) * pW; }
function toY(v: number) { return PAD.top + pH - ((v - YMIN) / (YMAX - YMIN)) * pH; }

function rollingMean(data: number[], w: number): (number | null)[] {
    return data.map((_, i) => {
        if (i < w - 1) return null;
        const sl = data.slice(i - w + 1, i + 1);
        return +(sl.reduce((a, b) => a + b, 0) / sl.length).toFixed(2);
    });
}

const RAW_COLOR = "#3b82f6";
const SMOOTH_COLOR = "#f59e0b";
const GRID_COLOR = "#111827";

// ΓöÇΓöÇΓöÇ Props ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
interface Props { config?: RollingAverageConfig; }

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function RollingAveragePrimitive({ config: _config }: Props) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const [win, setWin] = useState(7);
    const [animating, setAnim] = useState(false);
    const [scanPos, setScanPos] = useState<number | null>(null);

    const rolling = rollingMean(DATA, win);

    const draw = useCallback((pos: number | null) => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext("2d")!;
        ctx.clearRect(0, 0, W, H);

        // Background
        ctx.fillStyle = "#0d0e1a"; ctx.fillRect(0, 0, W, H);

        // Grid lines
        ctx.strokeStyle = GRID_COLOR; ctx.lineWidth = 1;
        for (let i = 1; i <= 4; i++) {
            const y = PAD.top + (i / 5) * pH;
            ctx.beginPath(); ctx.moveTo(PAD.left, y); ctx.lineTo(PAD.left + pW, y); ctx.stroke();
        }

        // Raw signal (dim)
        ctx.beginPath();
        DATA.forEach((v, i) => { const x = toX(i), y = toY(v); i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
        ctx.strokeStyle = RAW_COLOR; ctx.lineWidth = 1; ctx.globalAlpha = 0.3; ctx.stroke(); ctx.globalAlpha = 1;

        // Window highlight box
        if (pos !== null && pos >= win - 1) {
            const x1 = toX(pos - win + 1), x2 = toX(pos);
            ctx.fillStyle = SMOOTH_COLOR + "14";
            ctx.fillRect(x1, PAD.top, x2 - x1, pH);
            ctx.strokeStyle = SMOOTH_COLOR + "55"; ctx.lineWidth = 1;
            ctx.strokeRect(x1, PAD.top, x2 - x1, pH);
        }

        // Rolling mean line up to pos
        const drawTo = pos ?? N - 1;
        ctx.beginPath();
        let started = false;
        rolling.forEach((v, i) => {
            if (v === null || i > drawTo) return;
            const x = toX(i), y = toY(v);
            if (!started) { ctx.moveTo(x, y); started = true; } else ctx.lineTo(x, y);
        });
        ctx.strokeStyle = SMOOTH_COLOR; ctx.lineWidth = 2.5;
        ctx.shadowColor = SMOOTH_COLOR; ctx.shadowBlur = 6; ctx.stroke(); ctx.shadowBlur = 0;

        // Current point
        if (pos !== null && rolling[pos] !== null) {
            ctx.beginPath(); ctx.arc(toX(pos), toY(rolling[pos]!), 6, 0, Math.PI * 2);
            ctx.fillStyle = SMOOTH_COLOR; ctx.shadowColor = SMOOTH_COLOR; ctx.shadowBlur = 14; ctx.fill(); ctx.shadowBlur = 0;
        }

        // Axes
        ctx.strokeStyle = "#252535"; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(PAD.left, PAD.top); ctx.lineTo(PAD.left, PAD.top + pH); ctx.lineTo(PAD.left + pW, PAD.top + pH); ctx.stroke();

        // Y labels
        ctx.fillStyle = "#374151"; ctx.font = "10px monospace"; ctx.textAlign = "right";
        [20, 35, 50, 65, 80].forEach(v => { ctx.fillText(String(v), PAD.left - 4, toY(v) + 4); });

        // Legend
        ctx.textAlign = "left"; ctx.globalAlpha = 0.5;
        ctx.fillStyle = RAW_COLOR; ctx.fillText("ΓöÇ raw signal", PAD.left + 4, PAD.top + 14);
        ctx.globalAlpha = 1;
        ctx.fillStyle = SMOOTH_COLOR; ctx.fillText(`ΓöÇ rolling mean (w=${win})`, PAD.left + 110, PAD.top + 14);
        if (pos !== null && rolling[pos]) {
            ctx.fillStyle = "#4a5568"; ctx.textAlign = "right";
            ctx.fillText(`╬╝ = ${rolling[pos]}`, PAD.left + pW - 4, PAD.top + 14);
        }
    }, [rolling, win]);

    // Initial draw
    useEffect(() => { draw(null); }, [draw]);

    // Animate scan
    const animate = useCallback(() => {
        setAnim(true);
        let pos = win - 1;
        function step() {
            setScanPos(pos); draw(pos);
            if (pos < N - 1) { pos++; animRef.current = setTimeout(step, 28); }
            else { setAnim(false); setScanPos(null); draw(null); }
        }
        step();
    }, [draw, win]);

    // Cleanup
    useEffect(() => () => { if (animRef.current) clearTimeout(animRef.current); }, []);

    const handleWinChange = (v: number) => {
        if (animRef.current) clearTimeout(animRef.current);
        setAnim(false); setScanPos(null);
        setWin(v);
    };

    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-6 select-none">

            {/* Header */}
            <div className="space-y-1">
                <h3 className="text-sm font-bold text-muted uppercase tracking-wider flex items-center gap-2">
                    <span className="material-symbols-outlined text-base">show_chart</span>
                    Rolling Average
                </h3>
                <p className="text-xs text-muted/60 max-w-lg">
                    A sliding window that computes the mean of the last <strong className="text-amber-400">w</strong> points,
                    smoothing noise while preserving the underlying trend.
                </p>
            </div>

            {/* Canvas */}
            <div className="border border-border rounded-xl overflow-hidden">
                <canvas ref={canvasRef} width={W} height={H} style={{ display: "block", maxWidth: "100%", height: "auto" }} />
            </div>

            {/* Controls */}
            <div className="flex flex-col md:flex-row gap-6 items-start">
                {/* Slider */}
                <div className="flex-1 space-y-3">
                    <div className="flex justify-between text-[10px]">
                        <span className="text-muted/50 uppercase tracking-widest">Window Size</span>
                        <span className="font-black text-amber-400 font-mono">w = {win} periods</span>
                    </div>
                    <input
                        type="range" min={2} max={30} step={1} value={win}
                        onChange={e => handleWinChange(+e.target.value)}
                        className="w-full cursor-pointer"
                        style={{ accentColor: SMOOTH_COLOR }}
                    />
                    <div className="flex justify-between text-[9px] text-muted/30">
                        <span>w=2 (jittery, responsive)</span>
                        <span>w=30 (smooth, lagging)</span>
                    </div>
                </div>

                {/* Button */}
                <button
                    onClick={animate}
                    disabled={animating}
                    className="shrink-0 px-6 py-3 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all"
                    style={{
                        background: animating ? "rgba(255,255,255,0.05)" : SMOOTH_COLOR + "cc",
                        color: animating ? "rgba(255,255,255,0.2)" : "#000",
                        cursor: animating ? "not-allowed" : "pointer",
                    }}
                >
                    {animating ? "ScanningΓÇª" : "Γû╢ Animate Window"}
                </button>
            </div>

            {/* Insight */}
            <div className="bg-amber-400/5 border border-amber-400/15 rounded-xl p-4 flex gap-3">
                <span className="material-symbols-outlined text-amber-400 text-sm mt-0.5">swap_horiz</span>
                <div className="text-[10px] text-muted/70 leading-relaxed space-y-1">
                    <p><strong className="text-amber-400">Small window</strong> ΓåÆ responsive but noisy. <strong className="text-amber-400">Large window</strong> ΓåÆ smooth but lags behind changes.</p>
                    <p className="font-mono text-muted/50">df[&apos;value&apos;].rolling(window={win}).mean()</p>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";

// ΓöÇΓöÇΓöÇ Constants & Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const CW = 740, CH = 460;
const SCALE = 80;

type SVDStage = 0 | 1 | 2 | 3; // unit, rotation1, stretch, rotation2

// ΓöÇΓöÇΓöÇ Math Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const identity = () => [1, 0, 0, 1];

const rotation = (deg: number) => {
    const r = (deg * Math.PI) / 180;
    return [Math.cos(r), -Math.sin(r), Math.sin(r), Math.cos(r)];
};

const stretch = (s1: number, s2: number) => [s1, 0, 0, s2];

const multiply = (A: number[], B: number[]) => [
    A[0] * B[0] + A[1] * B[2],
    A[0] * B[1] + A[1] * B[3],
    A[2] * B[0] + A[3] * B[2],
    A[2] * B[1] + A[3] * B[3],
];

const applyM = (M: number[], v: { x: number, y: number }) => ({
    x: M[0] * v.x + M[1] * v.y,
    y: M[2] * v.x + M[3] * v.y,
});

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function SVDPrimitive() {
    const [theta1, setTheta1] = useState(30);   // Vß╡Ç (First rotation)
    const [sigma1, setSigma1] = useState(2.0);  // ╬ú (Stretch x)
    const [sigma2, setSigma2] = useState(1.0);  // ╬ú (Stretch y)
    const [theta2, setTheta2] = useState(-20);  // U (Second rotation)
    const [stage, setStage] = useState<SVDStage>(3);

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const OX = CW / 2, OY = CH / 2;

    const currentMatrix = useMemo(() => {
        let M = identity();
        if (stage >= 1) M = multiply(rotation(theta1), M);
        if (stage >= 2) M = multiply(stretch(sigma1, sigma2), M);
        if (stage >= 3) M = multiply(rotation(theta2), M);
        return M;
    }, [theta1, theta2, sigma1, sigma2, stage]);

    // ΓöÇΓöÇΓöÇ Drawing Logic ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const drawGrid = (ctx: CanvasRenderingContext2D, M: number[], alpha: number, color: string) => {
        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        const range = 6;
        for (let x = -range; x <= range; x++) {
            const p1 = applyM(M, { x, y: -range });
            const p2 = applyM(M, { x, y: range });
            ctx.beginPath();
            ctx.moveTo(OX + p1.x * SCALE, OY - p1.y * SCALE);
            ctx.lineTo(OX + p2.x * SCALE, OY - p2.y * SCALE);
            ctx.stroke();
        }
        for (let y = -range; y <= range; y++) {
            const p1 = applyM(M, { x: -range, y });
            const p2 = applyM(M, { x: range, y });
            ctx.beginPath();
            ctx.moveTo(OX + p1.x * SCALE, OY - p1.y * SCALE);
            ctx.lineTo(OX + p2.x * SCALE, OY - p2.y * SCALE);
            ctx.stroke();
        }
        ctx.restore();
    };

    const drawUnitCircle = (ctx: CanvasRenderingContext2D, M: number[]) => {
        ctx.save();
        ctx.strokeStyle = "hsl(var(--rose-400))";
        ctx.lineWidth = 3;
        ctx.beginPath();
        for (let t = 0; t <= 2 * Math.PI + 0.1; t += 0.05) {
            const v = { x: Math.cos(t), y: Math.sin(t) };
            const p = applyM(M, v);
            const px = OX + p.x * SCALE;
            const py = OY - p.y * SCALE;
            if (t === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.stroke();

        // Draw major/minor axes of the resulting ellipse
        if (stage >= 2) {
            const axesM = stage === 2 ? multiply(stretch(sigma1, sigma2), rotation(theta1)) : currentMatrix;
            const v1 = applyM(axesM, { x: 1, y: 0 });
            const v2 = applyM(axesM, { x: 0, y: 1 });

            ctx.setLineDash([4, 4]);
            ctx.lineWidth = 1.5;
            ctx.strokeStyle = "rgba(255,255,255,0.4)";

            ctx.beginPath(); ctx.moveTo(OX, OY); ctx.lineTo(OX + v1.x * SCALE, OY - v1.y * SCALE); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(OX, OY); ctx.lineTo(OX + v2.x * SCALE, OY - v2.y * SCALE); ctx.stroke();
        }
        ctx.restore();
    };

    const drawBasis = (ctx: CanvasRenderingContext2D, M: number[]) => {
        const iLand = applyM(M, { x: 1, y: 0 });
        const jLand = applyM(M, { x: 0, y: 1 });

        const drawArrow = (to: { x: number, y: number }, color: string) => {
            const dx = to.x, dy = to.y;
            const len = Math.sqrt(dx * dx + dy * dy);
            if (len < 0.1) return;
            const px = OX + to.x * SCALE;
            const py = OY - to.y * SCALE;
            ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(OX, OY); ctx.lineTo(px, py); ctx.stroke();
            const angle = Math.atan2(-dy, dx);
            ctx.beginPath(); ctx.moveTo(px, py);
            ctx.lineTo(px - 10 * Math.cos(angle - 0.4), py + 10 * Math.sin(angle - 0.4));
            ctx.lineTo(px - 10 * Math.cos(angle + 0.4), py + 10 * Math.sin(angle + 0.4));
            ctx.closePath(); ctx.fill();
        };

        drawArrow(iLand, "hsl(var(--emerald-400))");
        drawArrow(jLand, "hsl(var(--primary))");
    };

    const render = useCallback(() => {
        const ctx = canvasRef.current?.getContext("2d");
        if (!ctx) return;

        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = "hsl(var(--surface))";
        ctx.fillRect(0, 0, CW, CH);

        // Base static grid
        drawGrid(ctx, identity(), 0.05, "white");

        // Transformed grid
        drawGrid(ctx, currentMatrix, 0.3, "hsl(var(--primary))");

        // Unit circle becomes Ellipse
        drawUnitCircle(ctx, currentMatrix);

        // Basis vectors
        drawBasis(ctx, currentMatrix);

        // Origin
        ctx.fillStyle = "white";
        ctx.beginPath(); ctx.arc(OX, OY, 4, 0, Math.PI * 2); ctx.fill();
    }, [currentMatrix]);

    useEffect(() => {
        render();
    }, [render]);

    const stageDescription = [
        "Identity: Unit circle and grid.",
        "Rotation Vß╡Ç: Rotating the input space to align with principal directions.",
        "Stretch ╬ú: Scaling along the perpendicular axes defined by singular values.",
        "Final Rotation U: Orienting the scaled space to its final destination."
    ];

    return (
        <div className="bg-surface/50 border border-border rounded-lg p-6 space-y-6 select-none">
            {/* Header */}
            <div className="flex flex-col lg:flex-row justify-between gap-6">
                <div className="space-y-4">
                    <div className="space-y-1">
                        <h3 className="text-sm font-bold text-muted uppercase tracking-wider flex items-center gap-2">
                            <span className="material-symbols-outlined text-base">layers</span>
                            Singular Value Decomposition
                        </h3>
                        <p className="text-xs text-muted/60 max-w-lg">
                            An objective decomposition of any linear map into three components: <strong>Rotate (Vß╡Ç)</strong>, <strong>Stretch (╬ú)</strong>, and <strong>Rotate (U)</strong>.
                        </p>
                    </div>

                    <div className="flex gap-2 p-1 bg-black/20 border border-border rounded-xl w-fit">
                        {[0, 1, 2, 3].map((s) => (
                            <button
                                key={s}
                                onClick={() => setStage(s as SVDStage)}
                                className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${stage === s ? "bg-primary text-white shadow-lg shadow-primary/20" : "text-muted/60 hover:text-muted"
                                    }`}
                            >
